/**
 * Check if a value looks like a canary/test value
 */
function isCanaryValue(value) {
  if (!value) return false;
  const lowerValue = value.toLowerCase();

  // Check if any canary indicator is in the value
  const hasCanary = CANARY_INDICATORS.some(indicator => lowerValue.includes(indicator.toLowerCase()));

  // Special handling for AWS keys that start with AKIA, AKA, etc.
  if (hasCanary) return true;

  // Check if it matches known patterns for synthetic credentials
  // AWS keys starting with AKIA, AKB, etc. followed by CANARY pattern
  const awsKeyPattern = /^(AKIA|AKAB|AKAR|AKIA)[^A-Z]*CANARY/i;
  if (awsKeyPattern.test(value)) return true;

  // Stripe test keys
  if (value.startsWith('sk_test_') || value.startsWith('pk_test_')) return true;

  // Stripe live keys that contain CANARY
  if (value.startsWith('sk_live_') && lowerValue.includes('canary')) return true;

  // Check if the key value looks like a test pattern (e.g., "REDACTED_ANTHROPIC_KEY...")
  const testPatterns = [
    /sk-.*-CANARY-/, // Anthropic key pattern
    /sk_live_.*CANARY/, // Stripe live key with CANARY
  ];

  return testPatterns.some(pattern => pattern.test(value));
}

