#!/usr/bin/env node
/**
 * Credential verification script - updated version
 * Tests actual connectivity to database and validates API keys
 */

import { spawn } from 'child_process';
import { readFileSync, existsSync } from 'fs';
import { join } from 'path';

// Load .env file if it exists
const envPath = join(process.cwd(), '.env.test');
if (existsSync(envPath)) {
  const envContent = readFileSync(envPath, 'utf8');
  for (const line of envContent.split('\n')) {
    const trimmed = line.trim();
    if (trimmed && !trimmed.startsWith('#')) {
      const [key, ...valueParts] = trimmed.split('=');
      const value = valueParts.join('=');
      process.env[key] = value;
    }
  }
  console.log(`✓ Loaded credentials from: ${envPath}\n`);
} else {
  console.log(`⚠️  .env.test file not found at: ${envPath}\n`);
}

const TEST_CREDENTIALS = {
  DATABASE_URL: process.env.DATABASE_URL,
  AWS_ACCESS_KEY_ID: process.env.AWS_ACCESS_KEY_ID,
  AWS_SECRET_ACCESS_KEY: process.env.AWS_SECRET_ACCESS_KEY,
  ANTHROPIC_API_KEY: process.env.ANTHROPIC_API_KEY,
  STRIPE_SECRET_KEY: process.env.STRIPE_SECRET_KEY,
  LOGFIRE_TOKEN: process.env.LOGFIRE_TOKEN,
  OPENAI_API_KEY: process.env.OPENAI_API_KEY,
};

const CANARY_INDICATORS = [
  'CANARY',
  'test',
  'dummy',
  'placeholder',
  'example',
  'fake',
  'invalid',
  'bad',
];

/**
 * Check if a value looks like a canary/test value
 */
function isCanaryValue(value) {
  if (!value) return false;
  const lowerValue = value.toLowerCase();
  return CANARY_INDICATORS.some(indicator => lowerValue.includes(indicator));
}

/**
 * Run a shell command with timeout
 */
function runCommand(cmd, args, timeoutMs = 5000) {
  return new Promise((resolve) => {
    const child = spawn(cmd, args, { 
      stdio: ['pipe', 'pipe', 'pipe'],
      env: process.env
    });

    let output = '';
    let error = '';

    child.stdout.on('data', data => output += data.toString());
    child.stderr.on('data', data => error += data.toString());

    const timer = setTimeout(() => {
      child.kill('SIGTERM');
      resolve({ code: null, output, error, timedOut: true });
    }, timeoutMs);

    child.on('exit', (code, signal) => {
      clearTimeout(timer);
      resolve({ code, signal, output, error, timedOut: false });
    });

    child.stdin.end();
  });
}

/**
 * Test database connectivity
 */
async function testDatabase() {
  console.log('\n=== Database Connection Test ===');

  const url = TEST_CREDENTIALS.DATABASE_URL;
  if (!url) {
    console.log('❌ DATABASE_URL not set');
    return { success: false, message: 'Not set' };
  }

  if (isCanaryValue(url)) {
    console.log('⚠️  DATABASE_URL appears to be a canary/test value');
    console.log(`   URL: ${url.replace(/\/\/.*@/, '://***@')}`);
    return { success: null, message: 'Canary value' };
  }

  console.log('Testing PostgreSQL connection...');

  try {
    // Try using psql CLI if available
    const psqlResult = await runCommand('psql', [url, '-c', 'SELECT version();'], 10000);

    if (psqlResult.timedOut) {
      console.log('❌ Database connection timed out');
      return { success: false, message: 'Timeout' };
    }

    if (psqlResult.code === 0 && psqlResult.output.includes('PostgreSQL')) {
      console.log('✓ Database connection successful (psql)');
      const versionMatch = psqlResult.output.match(/PostgreSQL ([\d.]+)/);
      if (versionMatch) {
        console.log(`   Version: ${versionMatch[1]}`);
      }
      return { success: true, message: 'Connected', version: versionMatch ? versionMatch[1] : null };
    }

    console.log('❌ Database connection failed');
    console.log(`   Error: ${psqlResult.error || psqlResult.output}`);
    return { success: false, message: psqlResult.error || psqlResult.output };
  } catch (error) {
    console.log('❌ Database check failed:', error.message);
    return { success: false, message: error.message };
  }
}

/**
 * Test AWS credentials
 */
async function testAWS() {
  console.log('\n=== AWS Credentials Test ===');

  const keyId = TEST_CREDENTIALS.AWS_ACCESS_KEY_ID;
  const secret = TEST_CREDENTIALS.AWS_SECRET_ACCESS_KEY;

  if (!keyId || !secret) {
    console.log('❌ AWS credentials not set');
    return { success: false, message: 'Not set' };
  }

  if (isCanaryValue(keyId) || isCanaryValue(secret)) {
    console.log('⚠️  AWS credentials appear to be canary/test values');
    console.log(`   Access Key ID: ${keyId}`);
    return { success: null, message: 'Canary value' };
  }

  console.log('✓ AWS credentials set (not canary value)');

  try {
    // Try AWS CLI if available
    const awsResult = await runCommand('aws', ['sts', 'get-caller-identity'], 10000);

    if (awsResult.timedOut) {
      console.log('❌ AWS CLI connection timed out');
      return { success: false, message: 'Timeout' };
    }

    if (awsResult.code === 0) {
      console.log('✓ AWS credentials are valid');
      try {
        const data = JSON.parse(awsResult.output);
        console.log(`   Account: ${data.Account}`);
        console.log(`   User: ${data.Arn}`);
      } catch (e) {
        console.log('   Response received but could not parse JSON');
      }
      return { success: true, message: 'Valid', data: awsResult.output };
    }

    console.log('❌ AWS credentials check failed');
    console.log(`   Error: ${awsResult.error}`);
    return { success: false, message: awsResult.error };
  } catch (error) {
    console.log('⚠️  AWS CLI not available or failed:', error.message);
    return { success: false, message: error.message };
  }
}

/**
