  if (!apiKey) {
    console.log('❌ ANTHROPIC_API_KEY not set');
    return { success: false, message: 'Not set' };
  }

  if (isCanaryValue(apiKey)) {
    console.log('⚠️  Anthropic API key appears to be a canary/test value');
    return { success: null, message: 'Canary value' };
  }

  console.log('✓ Anthropic API key set (not canary value)');

  try {
    // Use fetch if available (Node 18+)
    if (typeof fetch === 'function') {
      const response = await fetch('https://api.anthropic.com/v1/keys/valid', {
        method: 'GET',
        headers: {
          'x-api-key': apiKey,
          'anthropic-version': '2023-06-01',
          'content-type': 'application/json',
        },
        timeout: 10000,
      });

      if (response.ok) {
        console.log('✓ Anthropic API key appears valid');
        return { success: true, message: 'Valid', status: response.status };
      } else if (response.status === 401 || response.status === 403) {
        console.log('❌ Anthropic API key is invalid');
        return { success: false, message: 'Invalid', status: response.status };
      } else {
        console.log(`⚠️  Unexpected status: ${response.status}`);
        return { success: null, message: `Status ${response.status}`, status: response.status };
      }
    } else {
      console.log('⚠️  Fetch not available, skipping API test');
      return { success: null, message: 'Fetch unavailable' };
    }
  } catch (error) {
    console.log('❌ Anthropic API check failed:', error.message);
    return { success: false, message: error.message };
  }
}

/**
