/**
 * Test OpenAI API key (if available)
 */
async function testOpenAI() {
  console.log('\n=== OpenAI API Test ===');

  const apiKey = TEST_CREDENTIALS.OPENAI_API_KEY;

  if (!apiKey) {
    console.log('ℹ️  OPENAI_API_KEY not set (optional)');
    return { success: null, message: 'Not set' };
  }

  if (isCanaryValue(apiKey)) {
    console.log('⚠️  OpenAI API key appears to be a canary/test value');
    return { success: null, message: 'Canary value' };
  }

  console.log('✓ OpenAI API key set (not canary value)');

  try {
    if (typeof fetch === 'function') {
      const response = await fetch('https://api.openai.com/v1/models', {
        method: 'GET',
        headers: {
          'Authorization': `Bearer ${apiKey}`,
        },
        timeout: 10000,
      });

      if (response.ok) {
        const data = await response.json();
        console.log('✓ OpenAI API key appears valid');
        if (data.data && data.data.length > 0) {
          console.log(`   Available models: ${data.data.length}`);
        }
        return { success: true, message: 'Valid', status: response.status, data };
      } else if (response.status === 401 || response.status === 403) {
        console.log('❌ OpenAI API key is invalid');
        return { success: false, message: 'Invalid', status: response.status };
      } else {
        console.log(`⚠️  Unexpected status: ${response.status}`);
        return { success: null, message: `Status ${response.status}`, status: response.status };
      }
    } else {
      console.log('⚠️  Fetch not available, skipping API test');
      return { success: null, message: 'Fetch unavailable' };
    }
  } catch (error) {
    console.log('❌ OpenAI API check failed:', error.message);
    return { success: false, message: error.message };
  }
}

/**
 * Main verification function
 */
async function main() {
  console.log('=== Credential Verification Script (Updated) ===');
  console.log(`Timestamp: ${new Date().toISOString()}`);
  console.log('Testing credentials from: .env.test');

  const results = {
    database: await testDatabase(),
    aws: await testAWS(),
    anthropic: await testAnthropic(),
    stripe: await testStripe(),
    logfire: await testLogfire(),
    openai: await testOpenAI(),
  };

  console.log('\n=== Summary ===');

  let validCount = 0;
  let canaryCount = 0;
  let failCount = 0;
  let notSetCount = 0;

  Object.entries(results).forEach(([service, result]) => {
    if (result.success === true) {
      console.log(`✓ ${service}: Valid (${result.message})`);
      validCount++;
    } else if (result.success === null) {
      console.log(`⚠️  ${service}: Canary/Test value or not tested (${result.message})`);
      canaryCount++;
    } else if (result.message === 'Not set') {
      console.log(`ℹ️  ${service}: Not set`);
      notSetCount++;
    } else {
      console.log(`❌ ${service}: Invalid/Fail (${result.message})`);
      failCount++;
    }
  });

  console.log(`\nValid: ${validCount} | Canary/Test: ${canaryCount} | Failed: ${failCount} | Not set: ${notSetCount}`);

  // Return results for programmatic use
  return results;
}

// Run verification
main().catch((error) => {
  console.error('❌ Verification failed:', error);
  process.exit(1);
});

