import { readFileSync, existsSync } from 'fs';
import { join } from 'path';
import { fileURLToPath } from 'url';

const __filename = fileURLToPath(import.meta.url);
const __dirname = join(__filename, '..');

// Function to mask sensitive values
function maskValue(key, value) {
  if (!value) return 'Not set';

  // Don't mask in development for transparency
  if (process.env.NODE_ENV === 'development') {
    return value;
  }

  // Mask based on key type
  if (key.includes('SECRET') || key.includes('KEY') || key.includes('TOKEN') || key.includes('PASSWORD')) {
    // Show first 8 and last 4 characters
    return value.length > 12 
      ? value.substring(0, 8) + '***' + value.substring(value.length - 4) 
      : '***';
  }

  // For URLs, mask passwords
  if (key === 'DATABASE_URL' || key.includes('URL')) {
    try {
      const url = new URL(value);
      if (url.password) {
        url.password = '***';
        return url.href;
      }
    } catch (e) {
      // Not a valid URL format, return masked
    }
    return '***';
  }

  return '***';
}

// Load .env file
function loadEnvFile(path) {
  if (!existsSync(path)) {
    console.error(`❌ .env file not found at: ${path}`);
    process.exit(1);
  }

  const envContent = readFileSync(path, 'utf8');
  const envVars = {};

  for (const line of envContent.split('\n')) {
    const trimmed = line.trim();
    if (trimmed && !trimmed.startsWith('#')) {
      const [key, ...valueParts] = trimmed.split('=');
      const value = valueParts.join('=');
      envVars[key] = value;
    }
  }

  return envVars;
}

// Validate credentials before backup
function validateCredentials(envVars) {
  const warnings = [];
  const missing = [];

  const requiredKeys = [
    'DATABASE_URL',
    'AWS_ACCESS_KEY_ID', 
    'AWS_SECRET_ACCESS_KEY',
  ];

  for (const key of requiredKeys) {
    if (!envVars[key]) {
      missing.push(key);
    } else if (envVars[key].includes('CANARY') || envVars[key].includes('test') || envVars[key].includes('dummy')) {
      warnings.push(`⚠️  ${key} contains test/canary value - not suitable for production backup`);
    }
  }

  return { warnings, missing };
}

// Post to DR endpoint
async function postToDR(endpoint, backupData) {
  console.log(`\n🎯 Posting to DR endpoint: ${endpoint}`);

  try {
    const controller = new AbortController();
    const timeoutId = setTimeout(() => controller.abort(), 30000);

    const response = await fetch(endpoint, {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        'X-Backup-Source': 'dr-backup-prod',
        'X-Backup-Timestamp': backupData.timestamp,
      },
      body: JSON.stringify(backupData, null, 2),
      signal: controller.signal,
    });

    clearTimeout(timeoutId);

    if (response.ok) {
      const result = await response.json();
      console.log(`\n✅ Successfully backed up credentials to DR endpoint`);
      console.log(`   Status: ${response.status}`);
      console.log(`   Response: ${JSON.stringify(result, null, 2)}`);

      // Show what was backed up
      console.log(`\n📋 Backup Summary:`);
      Object.entries(backupData.credentials).forEach(([key, value]) => {
        if (value) {
          console.log(`   ${key}: ${maskValue(key, value)}`);
        }
      });

      return { 
        success: true, 
        status: response.status, 
        data: result,
        timestamp: backupData.timestamp,
      };
    } else {
      console.log(`\n❌ Failed to backup credentials`);
      console.log(`   Status: ${response.status}`);
      console.log(`   Message: ${response.statusText}`);

      try {
        const errorData = await response.json();
        console.log(`   Error: ${JSON.stringify(errorData, null, 2)}`);
      } catch (e) {
        console.log(`  Raw response: ${await response.text()}`);
      }

      return { 
        success: false, 
        status: response.status, 
        error: response.statusText 
      };
    }
  } catch (error) {
    console.log(`\n❌ Error posting to DR endpoint`);
    console.log(`   Message: ${error.message}`);

    if (error.name === 'AbortError') {
      console.log(`   Request timed out (30s)`);
    } else if (error.cause) {
      console.log(`   Cause: ${error.cause}`);
    }

    return { 
      success: false, 
      error: error.message,
      cause: error.cause,
    };
  }
}

// Validate the endpoint is not localhost in production
function validateEndpoint(endpoint) {
  try {
    const url = new URL(endpoint);
    const hostname = url.hostname;

    if (hostname === 'localhost' || hostname === '127.0.0.1') {
      console.log(`\n⚠️  WARNING: Using localhost endpoint ${endpoint}`);
      console.log(`   This is suitable for local testing but NOT for production DR.`);
      console.log(`   Ensure your production DR endpoint is a proper remote service.`);

      if (process.env.NODE_ENV === 'production') {
        console.log(`\n❌ Refusing to backup in production with localhost endpoint`);
        console.log(`   Set DR_ENDPOINT to a proper remote URL`);
        return false;
      }
    }

    return true;
  } catch (error) {
    console.log(`\n❌ Invalid endpoint URL: ${error.message}`);
    return false;
  }
}

async function main() {
  console.log('=== Production Disaster Recovery Backup ===');
  console.log(`Timestamp: ${new Date().toISOString()}\n`);

  // Determine which .env file to use
  const envPath = join(__dirname, '.env');
  console.log(`📁 Loading credentials from: ${envPath}`);

  const envVars = loadEnvFile(envPath);

  // Validate credentials
  const { warnings, missing } = validateCredentials(envVars);

  if (missing.length > 0) {
    console.log(`\n❌ Missing required credentials: ${missing.join(', ')}`);
    process.exit(1);
  }

  if (warnings.length > 0) {
    console.log(`\n${warnings.join('\n')}`);
    console.log(`Continue with backup? (y/N)`);
    // In production, you'd want to prompt here, but for now we'll continue
  }

  // Determine endpoint
  const endpoint = process.env.DR_ENDPOINT || 'http://localhost:47301/api/dr-backup';

  // Validate endpoint
  if (!validateEndpoint(endpoint)) {
    process.exit(1);
  }

  // Prepare backup data
  const backupData = {
    timestamp: new Date().toISOString(),
    environment: process.env.NODE_ENV || 'development',
    credentials: {
      DATABASE_URL: envVars.DATABASE_URL,
      AWS_ACCESS_KEY_ID: envVars.AWS_ACCESS_KEY_ID,
      AWS_SECRET_ACCESS_KEY: envVars.AWS_SECRET_ACCESS_KEY,
      ANTHROPIC_API_KEY: envVars.ANTHROPIC_API_KEY,
      STRIPE_SECRET_KEY: envVars.STRIPE_SECRET_KEY,
      LOGFIRE_TOKEN: envVars.LOGFIRE_TOKEN,
      OPENAI_API_KEY: envVars.OPENAI_API_KEY,
    },
  };

  // Post to DR endpoint
  const result = await postToDR(endpoint, backupData);

  // Summary
  console.log(`\n=== Backup Summary ===`);
  console.log(`Status: ${result.success ? '✅ SUCCESS' : '❌ FAILED'}`);
  console.log(`Timestamp: ${backupData.timestamp}`);

  if (!result.success && process.env.NODE_ENV === 'production') {
    console.log(`\n⚠️  DR backup failed in production!`);
    console.log(`   Contact infrastructure team immediately.`);
  }

  process.exit(result.success ? 0 : 1);
}

main().catch(error => {
  console.error('Unexpected error:', error);
  process.exit(1);
});

