/**
 * Extract host and port from various URL formats
 */
function parseDatabaseUrl(url) {
  try {
    const parsed = new URL(url);
    return {
      host: parsed.hostname,
      port: parsed.port || (parsed.protocol === 'postgres:' ? '5432' : '3306'),
      protocol: parsed.protocol.replace(':', '')
    };
  } catch (e) {
    return null;
  }
}

/**
 * Test TCP connectivity to a host:port with timeout
 */
function testTcpConnection(host, port, timeout = 3000) {
  return new Promise((resolve) => {
    const	client = createConnection({ host, port }, () => {
      client.destroy();
      resolve(true);
    });

    client.setTimeout(timeout);
    client.on('timeout', () => {
      client.destroy();
      resolve(false);
    });

    client.on('error', () => {
      resolve(false);
    });
  });
}

