 */

const { readFileSync, existsSync } = require('fs');
const path = require('path');
const http = require('http');

const __dirname = __filename === '' ? '.' : path.dirname(__filename);

// Load .env file if it exists
const envPath = path.join(__dirname, '.env.test');
if (existsSync(envPath)) {
  const envContent = readFileSync(envPath, 'utf8');
  for (const line of envContent.split('\n')) {
    const trimmed = line.trim();
    if (trimmed && !trimmed.startsWith('#')) {
      const [key, ...valueParts] = trimmed.split('=');
      const value = valueParts.join('=');
      process.env[key] = value;
    }
  }
  console.log('✓ Loaded credentials from: .env.test\n');
}

const TEST_CREDENTIALS = {
  DATABASE_URL: process.env.DATABASE_URL,
  AWS_ACCESS_KEY_ID: process.env.AWS_ACCESS_KEY_ID,
  AWS_SECRET_ACCESS_KEY: process.env.AWS_SECRET_ACCESS_KEY,
  ANTHROPIC_API_KEY: process.env.ANTHROPIC_API_KEY,
  STRIPE_SECRET_KEY: process.env.STRIPE_SECRET_KEY,
  LOGFIRE_TOKEN: process.env.LOGFIRE_TOKEN,
};

const CANARY_INDICATORS = [
  'CANARY',
  'TEST',
  'DUMMY',
  'PLACEHOLDER',
  'EXAMPLE',
  'FAKE',
  'INVALID',
  'BAD',
];

// Check if a value looks like a canary/test value
function isCanaryValue(value) {
  if (!value) return false;
  const lowerValue = value.toLowerCase();
  return CANARY_INDICATORS.some(indicator => lowerValue.includes(indicator.toLowerCase()));
}

// Check database connectivity using psql if available
function testDatabase() {
  console.log('=== Database Connection Test ===');

  const url = TEST_CREDENTIALS.DATABASE_URL;
  if (!url) {
    console.log('❌ DATABASE_URL not set');
    return { status: 'error', message: 'Not set' };
  }

  if (isCanaryValue(url)) {
    console.log('⚠️  DATABASE_URL appears to be a canary/test value');
    console.log(`   URL: ${url.replace(/\/\/.*@/, '://***@')}`);
    return { 
      status: 'canary', 
      message: 'Synthetic test value - cannot verify connectivity' 
    };
  }

  const { spawn } = require('child_process');
  return new Promise((resolve) => {
    const child = spawn('psql', [url, '-c', 'SELECT 1'], {
      timeout: 5000,
    });

    let output = '';
    let error = '';

    child.stdout.on('data', data => {
      output += data.toString();
    });
    child.stderr.on('data', data => {
      error += data.toString();
    });

    child.on('error', (error) => {
      console.log(`❌ Database verification failed: ${error.message}`);
      resolve({ status: 'error', message: error.message });
    });

    child.on('exit', (code) => {
      if (code === 0 && output.includes('1')) {
        console.log('✓ Database connection successful');
        resolve({ status: 'valid', message: 'Connection successful' });
      } else {
        console.log('❌ Database connection failed');
        console.log(`   Error: ${error || output}`);
        resolve({ status: 'invalid', message: error || output });
      }
    });
  });
}

// Check AWS credentials
async function testAWS() {
  console.log('\n=== AWS Credentials Test ===');

  const keyId = TEST_CREDENTIALS.AWS_ACCESS_KEY_ID;
  const secret = TEST_CREDENTIALS.AWS_SECRET_ACCESS_KEY;

  if (!keyId || !secret) {
    console.log('❌ AWS credentials not set');
    return { status: 'error', message: 'Not set' };
  }

  if (isCanaryValue(keyId) || isCanaryValue(secret)) {
    console.log('⚠️  AWS credentials appear to be canary/test values');
    console.log(`   Access Key ID: ${keyId}`);
    return { 
      status: 'canary', 
      message: 'Synthetic test value - cannot verify connectivity' 
    };
  }

  console.log('✓ AWS credentials set (not canary values)');

  const { spawn } = require('child_process');
  return new Promise((resolve) => {
    const child = spawn('aws', ['sts', 'get-caller-identity'], {
      env: {
        ...process.env,
        AWS_ACCESS_KEY_ID: keyId,
        AWS_SECRET_ACCESS_KEY: secret,
      },
      timeout: 10000,
    });

    let output = '';
    let error = '';

    child.stdout.on('data', data => {
      output += data.toString();
    });
    child.stderr.on('data', data => {
      error += data.toString();
    });

    child.on('error', (error) => {
      console.log(`❌ AWS verification failed: ${error.message}`);
      resolve({ status: 'error', message: error.message });
    });

    child.on('exit', (code) => {
      if (code === 0) {
        console.log('✓ AWS credentials are valid');
        resolve({ status: 'valid', message: 'Authentication successful' });
      } else {
        console.log('❌ AWS credentials are invalid');
        console.log(`   Error: ${error || output}`);
        resolve({ status: 'invalid', message: error || output });
      }
    });
  });
}

// HTTP request helper
function makeRequest(url, options = {}) {
  return new Promise((resolve) => {
    const req = http.request(url, {
      method: 'GET',
      timeout: 10000,
      ...options,
    }, (res) => {
      let data = '';
      res.on('data', chunk => data += chunk);
      res.on('end', () => {
        resolve({
          statusCode: res.statusCode,
          data: data,
          headers: res.headers,
        });
      });
    });

    req.on('error', (error) => {
      resolve({ error: error.message });
    });

    req.on('timeout', () => {
      req.destroy();
      resolve({ error: 'Request timeout' });
    });

    req.end();
  });
}

