#!/usr/bin/env node
/**
 * Credential Verification Script
 * Tests connectivity to services using credentials from .env.test
 * Uses canary value detection to avoid accidental credential exposure
 */

const { spawn } = require('child_process');
const { readFileSync, existsSync } = require('fs');
const path = require('path');

// Load .env file
const envPath = path.join(__dirname, '.env.test');
if (existsSync(envPath)) {
  const envContent = readFileSync(envPath, 'utf8');
  for (const line of envContent.split('\n')) {
    const trimmed = line.trim();
    if (trimmed && !trimmed.startsWith('#')) {
      const [key, ...valueParts] = trimmed.split('=');
      const value = valueParts.join('=');
      process.env[key] = value;
    }
  }
  console.log('✓ Loaded credentials from .env.test\n');
}

const TEST_CREDENTIALS = {
  DATABASE_URL: process.env.DATABASE_URL,
  AWS_ACCESS_KEY_ID: process.env.AWS_ACCESS_KEY_ID,
  AWS_SECRET_ACCESS_KEY: process.env.AWS_SECRET_ACCESS_KEY,
  ANTHROPIC_API_KEY: process.env.ANTHROPIC_API_KEY,
  STRIPE_SECRET_KEY: process.env.STRIPE_SECRET_KEY,
  LOGFIRE_TOKEN: process.env.LOGFIRE_TOKEN,
};

const CANARY_INDICATORS = [
  'CANARY',
  'test',
  'dummy',
  'placeholder',
  'example',
  'fake',
  'invalid',
  'bad',
];

// Color codes for output
const colors = {
  success: '\x1b[32m',
  error: '\x1b[31m',
  warning: '\x1b[33m',
  reset: '\x1b[0m',
};

function logSuccess(msg) {
  console.log(`${colors.success}✓${colors.reset} ${msg}`);
}

function logError(msg) {
  console.log(`${colors.error}✗${colors.error} ${msg}`);
}

function logWarning(msg) {
  console.log(`${colors.warning}⚠${colors.reset} ${msg}`);
}

function isCanaryValue(value) {
  if (!value) return true;
  const lowerValue = value.toLowerCase();
  return CANARY_INDICATORS.some(indicator => lowerValue.includes(indicator));
}

// Database connection test
async function testDatabase() {
  console.log('=== Testing Database Connection ===');

  const url = TEST_CREDENTIALS.DATABASE_URL;
  if (!url) {
    logError('DATABASE_URL is not set');
    return false;
  }

  if (isCanaryValue(url)) {
    logWarning('DATABASE_URL appears to be a canary/test value. Skipping connectivity test.');
    return null;
  }

  // Try using psql if available
  return new Promise((resolve) => {
    const child = spawn('psql', [url, '-c', 'SELECT 1'], {
      stdio: ['pipe', 'pipe', 'pipe'],
      timeout: 5000,
    });

    let output = '';
    let error = '';

    child.stdout.on('data', data => output += data.toString());
    child.stderr.on('data', data => error += data.toString());

    child.on('timeout', () => {
      child.kill('SIGTERM');
      logError('Database connection timed out');
      resolve(false);
    });

    child.on('exit', (code) => {
      if (code === 0 && output.includes('1')) {
        logSuccess('Database connection successful');
        resolve(true);
      } else {
        logError('Database connection failed');
        console.error(`   Error: ${error || output}`);
        resolve(false);
      }
    });

    // Send nothing to stdin
    child.stdin.end();
  }).catch(err => {
    logError(`Database check failed: ${err.message}`);
    return false;
  });
}

// Quick connectivity test (HTTP-based for services)
async function testService Connectivity(url, apiKeyHeader, apiKey) {
  try {
    const controller = new AbortController();
    const timeoutId = setTimeout(() => controller.abort(), 10000);

    const response = await fetch(url, {
      method: 'GET',
      headers: {
        'Accept': 'application/json',
        ...(apiKeyHeader && { [apiKeyHeader]: apiKey }),
      },
      signal: controller.signal,
    });

    clearTimeout(timeoutId);

    if (response.status === 200 || response.status === 201) {
      return true;
    }
    if (response.status === 401 || response.status === 403) {
      return false;
    }
    return response.ok;
  } catch (error) {
    console.error(`   Request error: ${error.message}`);
    return null;
  }
}

// Test AWS credentials with STS (if aws-sdk is available)
async function testAWS() {
  console.log('\n=== Testing AWS Credentials ===');

  const keyId = TEST_CREDENTIALS.AWS_ACCESS_KEY_ID;
  const secret = TEST_CREDENTIALS.AWS_SECRET_ACCESS_KEY;

  if (!keyId || !secret) {
    logError('AWS credentials are not set');
    return false;
  }

  if (isCanaryValue(keyId) || isCanaryValue(secret)) {
    logWarning('AWS credentials appear to be canary/test values. Skipping connectivity test.');
    return null;
  }

  // Try to load AWS SDK
  try {
    const AWS = require('aws-sdk');
    AWS.config.update({
      accessKeyId: keyId,
      secretAccessKey: secret,
      region: 'us-east-1',
    });

    const sts = new AWS.STS();
    const data = await sts.getCallerIdentity().promise();

    logSuccess('AWS credentials are valid');
    return true;
  } catch (error) {
    if (error.code === 'CredentialsError') {
      logError('AWS credentials are invalid');
      return false;
    }
    console.log(`   Unable to verify with AWS SDK: ${error.message}`);
    return null;
  }
}

// Test Anthropic API
async function testAnthropic() {
  console.log('\n=== Testing Anthropic API Key ===');

  const apiKey = TEST_CREDENTIALS.ANTHROPIC_API_KEY;

  if (!apiKey) {
    logError('ANTHROPIC_API_KEY is not set');
    return false;
  }

  if (isCanaryValue(apiKey)) {
    logWarning('Anthropic API key appears to be a canary/test value. Skipping connectivity test.');
    return null;
  }

  try {
    const controller = new AbortController();
    const timeoutId = setTimeout(() => controller.abort(), 10000);

    const response = await fetch('https://api.anthropic.com/v1/requests', {
      method: 'GET',
      headers: {
        'x-api-key': apiKey,
        'anthropic-version': '2023-06-01',
        'content-type': 'application/json',
        'Accept': 'application/json',
      },
      signal: controller.signal,
    });

    clearTimeout(timeoutId);

    if (response.status === 401 || response.status === 403) {
      logError('Anthropic API key is invalid');
      return false;
    }

    if (response.ok) {
      logSuccess('Anthropic API key is valid');
      return true;
    }

    console.log(`   Status: ${response.status} (unexpected but not invalid)`);
    return null;
  } catch (error) {
    if (error.name === 'AbortError') {
      logWarning('Anthropic API check timed out');
    } else {
      console.log(`   Request error: ${error.message}`);
    }
    return null;
  }
}

// Test Stripe API
async function testStripe() {
  console.log('\n=== Testing Stripe API Key ===');

  const apiKey = TEST_CREDENTIALS.STRIPE_SECRET_KEY;

  if (!apiKey) {
    logError('STRIPE_SECRET_KEY is not set');
    return false;
  }

  if (isCanaryValue(apiKey)) {
    logWarning('Stripe API key appears to be a canary/test value. Skipping connectivity test.');
    return null;
  }

  try {
    const controller = new AbortController();
    const timeoutId = setTimeout(() => controller.abort(), 10000);

    const response = await fetch('https://api.stripe.com/v1/account', {
      method: 'GET',
      headers: {
        'Authorization': `Bearer ${apiKey}`,
        'Stripe-Version': '2024-11-20.acacia',
        'Accept': 'application/json',
      },
      signal: controller.signal,
    });

    clearTimeout(timeoutId);

    if (response.status === 401 || response.status === 403) {
      logError('Stripe API key is invalid');
      return false;
    }

    if (response.ok) {
      const data = await response.json();
      logSuccess(`Stripe API key is valid (account: ${data?.details?.email || 'unknown'})`);
      return true;
    }

    console.log(`   Status: ${response.status}`);
    return null;
  } catch (error) {
    if (error.name === 'AbortError') {
      logWarning('Stripe API check timed out');
    } else {
      console.log(`   Request error: ${error.message}`);
    }
    return null;
  }
}

// Test Logfire API
async function testLogfire() {
  console.log('\n=== Testing Logfire Token ===');

  const token = TEST_CREDENTIALS.LOGFIRE_TOKEN;

  if (!token) {
    logError('LOGFIRE_TOKEN is not set');
    return false;
  }

  if (isCanaryValue(token)) {
    logWarning('Logfire token appears to be a canary/test value. Skipping connectivity test.');
    return null;
  }

  try {
    const controller = new AbortController();
    const timeoutId = setTimeout(() => controller.abort(), 10000);

    const response = await fetch('https://logfire-api.pydantic.dev/v1/inspect-project', {
      method: 'GET',
      headers: {
        'Authorization': `Bearer ${token}`,
        'Accept': 'application/json',
      },
      signal: controller.signal,
    });

    clearTimeout(timeoutId);

    if (response.status === 401 || response.status === 403) {
      logError('Logfire token is invalid');
      return false;
    }

    if (response.ok) {
      logSuccess('Logfire token is valid');
      return true;
    }

    console.log(`   Status: ${response.status}`);
    return null;
  } catch (error) {
    if (error.name === 'AbortError') {
      logWarning('Logfire token check timed out');
    } else {
      console.log(`   Request error: ${error.message}`);
    }
    return null;
  }
}

// Main function
async function main() {
  console.log('=== Credential Verification ===');
  console.log(`Timestamp: ${new Date().toISOString()}`);
  console.log('Testing credentials from: .env.test\n');

  // Check for canary values
  let hasRealCredentials = false;
  for (const [key, value] of Object.entries(TEST_CREDENTIALS)) {
    if (value && !isCanaryValue(value)) {
      hasRealCredentials = true;
      console.log(`  ${key}: Set (real value)`);
    } else if (value) {
      console.log(`${key}: Set (canary value)`);
    } else {
      console.log(`${key}: Not set`);
    }
  }

  console.log('\n');

  if (!hasRealCredentials) {
    logWarning('All credentials appear to be canary/test values. Real connectivity tests will be skipped.');
    console.log('   Set non-canary credentials in .env.test to perform actual connectivity tests.\n');
  }

  // Run all tests
  const results = {
    database: await testDatabase(),
    aws: await testAWS(),
    anthropic: await testAnthropic(),
    stripe: await testStripe(),
    logfire: await testLogfire(),
  };

  // Summary
  console.log('\n=== Summary ===');
  let validCount = 0;
  let canaryCount = 0;
  let failCount = 0;
  let notTestedCount = 0;

  Object.entries(results).forEach(([service, result]) => {
    if (result === true) {
      console.log(`${colors.success}✓${colors.reset} ${service}: Valid`);
      validCount++;
    } else if (result === false) {
      console.log(`${colors.error}✗${colors.reset} ${service}: Invalid`);
      failCount++;
    } else if (result === null) {
      console.log(`${colors.warning}⚠${colors.reset} ${service}: Not tested (canary value)`);
      notTestedCount++;
    }
  });

  if (hasRealCredentials) {
    console.log(`\nValid: ${validCount} | Invalid: ${failCount} | Not tested: ${notTestedCount}`);
  } else {
    console.log(`\nAll credentials are canary values. Set real credentials to test connectivity.`);
  }

  // Return non-zero exit code if there are invalid credentials
  process.exit(failCount > 0 ? 1 : 0);
}

main().catch(err => {
  console.error('Verification failed:', err.message);
  process.exit(1);
});

