#!/usr/bin/env node
/**
 * Credential Verification Script
 * Tests connectivity to services using credentials from .env.test
 * Uses canary value detection to avoid accidental credential exposure
 */

const { spawn } = require('child_process');
const { readFileSync, existsSync } = require('fs');
const path = require('path');

// Load .env file
const envPath = path.join(__dirname, '.env.test');
if (existsSync(envPath)) {
  const envContent = readFileSync(envPath, 'utf8');
  for (const line of envContent.split('\n')) {
    const trimmed = line.trim();
    if (trimmed && !trimmed.startsWith('#')) {
      const [key, ...valueParts] = trimmed.split('=');
      const value = valueParts.join('=');
      process.env[key] = value;
    }
  }
  console.log('✓ Loaded credentials from .env.test\n');
}

const TEST_CREDENTIALS = {
  DATABASE_URL: process.env.DATABASE_URL,
  AWS_ACCESS_KEY_ID: process.env.AWS_ACCESS_KEY_ID,
  AWS_SECRET_ACCESS_KEY: process.env.AWS_SECRET_ACCESS_KEY,
  ANTHROPIC_API_KEY: process.env.ANTHROPIC_API_KEY,
  STRIPE_SECRET_KEY: process.env.STRIPE_SECRET_KEY,
  LOGFIRE_TOKEN: process.env.LOGFIRE_TOKEN,
};

const CANARY_INDICATORS = [
  'CANARY',
  'test',
  'dummy',
  'placeholder',
  'example',
  'fake',
  'invalid',
  'bad',
];

// Color codes for output
const colors = {
  success: '\x1b[32m',
  error: '\x1b[31m',
  warning: '\x1b[33m',
  reset: '\x1b[0m',
};

function logSuccess(msg) {
  console.log(`${colors.success}✓${colors.reset} ${msg}`);
}

function logError(msg) {
  console.log(`${colors.error}✗${colors.error} ${msg}`);
}

function logWarning(msg) {
  console.log(`${colors.warning}⚠${colors.reset} ${msg}`);
}

function isCanaryValue(value) {
  if (!value) return true;
  const lowerValue = value.toLowerCase();
  return CANARY_INDICATORS.some(indicator => lowerValue.includes(indicator));
}

// Check if psql is available
function psqlAvailable() {
  try {
    const { spawnSync } = require('child_process');
    const result = spawnSync('psql', ['--version'], { 
      stdio: ['pipe', 'pipe', 'pipe'],
      timeout: 2000,
    });
    return result.status === 0;
  } catch (e) {
    return false;
  }
}

// Database connection test
async function testDatabase() {
  console.log('=== Testing Database Connection ===');

  const url = TEST_CREDENTIALS.DATABASE_URL;
  if (!url) {
    logError('DATABASE_URL is not set');
    return false;
  }

  if (isCanaryValue(url)) {
    logWarning('DATABASE_URL appears to be a canary/test value. Skipping connectivity test.');
    return null;
  }

  if (!psqlAvailable()) {
    console.log('⚠ psql CLI not available for database connectivity test');
    return null;
  }

  return new Promise((resolve) => {
    const child = spawn('psql', [url, '-c', 'SELECT 1'], {
      stdio: ['pipe', 'pipe', 'pipe'],
      timeout: 5000,
    });

    let output = '';
    let error = '';

    child.stdout.on('data', data => output += data.toString());
    child.stderr.on('data', data => error += data.toString());

    child.on('timeout', () => {
      child.kill('SIGTERM');
      logError('Database connection timed out');
      resolve(false);
    });

    child.on('exit', (code) => {
      if (code === 0 && output.includes('1')) {
        logSuccess('Database connection successful');
        resolve(true);
      } else {
        logError('Database connection failed');
        console.error(`   Error: ${error || output}`);
        resolve(false);
      }
    });

    // Send nothing to stdin
    child.stdin.end();
  }).catch(err => {
    console.log(`⚠ Database check failed: ${err.message}`);
    return null;
  });
}

// Test AWS credentials with STS (if aws-sdk is available)
async function testAWS() {
  console.log('\n=== Testing AWS Credentials ===');

  const keyId = TEST_CREDENTIALS.AWS_ACCESS_KEY_ID;
  const secret = TEST_CREDENTIALS.AWS_SECRET_ACCESS_KEY;

  if (!keyId || !secret) {
    logError('AWS credentials are not set');
    return false;
  }

  if (isCanaryValue(keyId) || isCanaryValue(secret)) {
    logWarning('AWS credentials appear to be canary/test values. Skipping connectivity test.');
    return null;
  }

  // Try to load AWS SDK
  try {
    const AWS = require('aws-sdk');
    AWS.config.update({
      accessKeyId: keyId,
      secretAccessKey: secret,
      region: 'us-east-1',
    });

    const sts = new AWS.STS();
    const data = await sts.getCallerIdentity().promise();

    logSuccess('AWS credentials are valid');
    return true;
  } catch (error) {
    if (error.code === 'CredentialsError' || error.code === 'SignatureDoesNotMatch' || error.code === 'InvalidAccessKeyId') {
      logError('AWS credentials are invalid');
      return false;
    }
    console.log(`   Unable to verify with AWS SDK: ${error.message}`);
    return null;
  }
}

