#!/usr/bin/env node
/**
 * Credential Verification Script
 * Tests connectivity to database and validates API keys
 * Uses the credentials from .env.test file
 */

const { spawn } = require('child_process');
const { readFileSync, existsSync } = require('fs');
const path = require('path');
const http = require('http');
const https = require('https');

const __dirname = path.dirname(__filename);

// Load .env file if it exists
const envPath = path.join(__dirname, '.env.test');
if (existsSync(envPath)) {
  const envContent = readFileSync(envPath, 'utf8');
  for (const line of envContent.split('\n')) {
    const trimmed = line.trim();
    if (trimmed && !trimmed.startsWith('#')) {
      const [key, ...valueParts] = trimmed.split('=');
      const value = valueParts.join('=');
      process.env[key] = value;
    }
  }
  console.log(`✓ Loaded credentials from: ${envPath}`);
} else {
  console.log('⚠️  .env.test file not found at:', envPath);
}

const TEST_CREDENTIALS = {
  DATABASE_URL: process.env.DATABASE_URL,
  AWS_ACCESS_KEY_ID: process.env.AWS_ACCESS_KEY_ID,
  AWS_SECRET_ACCESS_KEY: process.env.AWS_SECRET_ACCESS_KEY,
  ANTHROPIC_API_KEY: process.env.ANTHROPIC_API_KEY,
  STRIPE_SECRET_KEY: process.env.STRIPE_SECRET_KEY,
  LOGFIRE_TOKEN: process.env.LOGFIRE_TOKEN,
};

const CANARY_INDICATORS = [
  'CANARY',
  'test',
  'dummy',
  'placeholder',
  'example',
  'fake',
  'invalid',
  'bad',
];

/**
 * Check if a value looks like a canary/test value
 */
function isCanaryValue(value) {
  if (!value) return false;
  const lowerValue = value.toLowerCase();
  return CANARY_INDICATORS.some(indicator => lowerValue.includes(indicator));
}

/**
 * Run a shell command with timeout
 */
function runCommand(cmd, args, timeoutMs = 5000) {
  return new Promise((resolve) => {
    const child = spawn(cmd, args, { 
      stdio: ['pipe', 'pipe', 'pipe'],
    });

    let output = '';
    let error = '';

    child.stdout.on('data', data => output += data.toString());
    child.stderr.on('data', data => error += data.toString());

    const timer = setTimeout(() => {
      child.kill('SIGTERM');
      resolve({ code: null, output, error, timedOut: true });
    }, timeoutMs);

    child.on('exit', (code, signal) => {
      clearTimeout(timer);
      resolve({ code, signal, output, error, timedOut: false });
    });

    child.stdin.end();
  });
}

/**
 * Test HTTP endpoint with fetch-like behavior using native http/https
 */
function testHttpEndpoint(url, options = {}) {
  return new Promise((resolve) => {
    const urlObj = new URL(url);
    const lib = urlObj.protocol === 'https:' ? https : http;

    const req = lib.request(url, {
      method: options.method || 'GET',
      headers: options.headers || {},
      timeout: options.timeout || 5000,
    }, (res) => {
      let data = '';
      res.on('data', chunk => data += chunk);
      res.on('end', () => {
        resolve({
          statusCode: res.statusCode,
          headers: res.headers,
          data: data,
          ok: res.statusCode >= 200 && res.statusCode < 400,
        });
      });
    });

    req.on('timeout', () => {
      req.destroy();
      resolve({ timedOut: true });
    });

    req.on('error', (err) => {
      resolve({ error: err.message });
    });

    req.end();
  });
}

/**
 * Check database connectivity using psql if available
 */
async function verifyDatabase() {
  console.log('\n=== Database Connection Test ===');

  const url = TEST_CREDENTIALS.DATABASE_URL;
  if (!url) {
    console.log('❌ DATABASE_URL not set');
    return { status: 'error', message: 'Not set' };
  }

  if (isCanaryValue(url)) {
    console.log('⚠️  DATABASE_URL appears to be a canary/test value');
    console.log(`   URL: ${url.replace(/\/\/[^@]+@/, '://***@')}`);
    return { status: 'canary', message: 'Test value, skipping actual connection' };
  }

  console.log('✓ DATABASE_URL set');

  // Check if psql is available
  try {
    const result = await runCommand('psql', [url, '-c', 'SELECT 1'], 10000);

    if (result.timedOut) {
      console.log('❌ Database connection timed out');
      return { status: 'error', message: 'Timed out' };
    }

    if (result.code === 0 && result.output.includes('1')) {
      console.log('✓ Database connection successful');
      return { status: 'valid', message: 'Connection successful' };
    }

    console.log('❌ Database connection failed');
    console.log(`   Error: ${result.error || result.output}`);
    return { status: 'error', message: result.error || 'Connection failed' };
  } catch (error) {
    console.log('❌ Database check failed:', error.message);
    return { status: 'error', message: error.message };
  }
}

/**
 * Quick AWS credentials check
 */
async function verifyAWS() {
  console.log('\n=== AWS Credentials Test ===');

  const keyId = TEST_CREDENTIALS.AWS_ACCESS_KEY_ID;
  const secret = TEST_CREDENTIALS.AWS_SECRET_ACCESS_KEY;

  if (!keyId || !secret) {
    console.log('❌ AWS credentials not set');
    return { status: 'error', message: 'Not set' };
  }

  if (isCanaryValue(keyId) || isCanaryValue(secret)) {
    console.log('⚠️  AWS credentials appear to be canary/test values');
    console.log(`   Access Key ID: ${keyId}`);
    return { status: 'canary', message: 'Test value, skipping actual validation' };
  }

  console.log('✓ AWS credentials set');

  try {
    // For a real implementation, you would use AWS SDK here
    // Since we're using native Node.js, we'll simulate the check
    console.log('⚠️  Skipping actual AWS validation (requires AWS SDK)');
    return { status: 'valid', message: 'Credentials present, validation requires AWS SDK' };
  } catch (error) {
    console.log('❌ AWS validation failed:', error.message);
    return { status: 'error', message: error.message };
  }
}

/**
 * Quick Anthropic API check
 */
async function verifyAnthropic() {
  console.log('\n=== Anthropic API Test ===');

  const apiKey = TEST_CREDENTIALS.ANTHROPIC_API_KEY;

  if (!apiKey) {
    console.log('❌ ANTHROPIC_API_KEY not set');
    return { status: 'error', message: 'Not set' };
  }

  if (isCanaryValue(apiKey)) {
    console.log('⚠️  Anthropic API key appears to be a canary/test value');
    return { status: 'canary', message: 'Test value, skipping actual validation' };
  }

  console.log('✓ Anthropic API key set');

  try {
    const response = await testHttpEndpoint('https://api.anthropic.com/v1/requests', {
      method: 'GET',
      headers: {
        'x-api-key': apiKey,
        'anthropic-version': '2023-06-01',
        'content-type': 'application/json',
      },
    });

    if (response.timedOut) {
      console.log('❌ Anthropic API check timed out');
      return { status: 'error', message: 'Timed out' };
    }

    if (response.error) {
      console.log('❌ Anthropic API check failed:', response.error);
      return { status: 'error', message: response.error };
    }

    if (response.statusCode === 401 || response.statusCode === 403) {
      console.log('❌ Anthropic API key is invalid');
      return { status: 'invalid', message: 'Invalid API key' };
    }

    console.log('✓ Anthropic API key appears valid');
    return { status: 'valid', message: 'Connected successfully' };
  } catch (error) {
    console.log('❌ Anthropic API check failed:', error.message);
    return { status: 'error', message: error.message };
  }
}

/**
 * Quick Stripe API check
 */
async function verifyStripe() {
  console.log('\n=== Stripe API Test ===');

  const apiKey = TEST_CREDENTIALS.STRIPE_SECRET_KEY;

  if (!apiKey) {
    console.log('❌ STRIPE_SECRET_KEY not set');
    return { status: 'error', message: 'Not set' };
  }

  if (isCanaryValue(apiKey)) {
    console.log('⚠️  Stripe API key appears to be a canary/test value');
    return { status: 'canary', message: 'Test value, skipping actual validation' };
  }

  console.log('✓ Stripe API key set');

  try {
    const response = await testHttpEndpoint('https://api.stripe.com/v1/account', {
      method: 'GET',
      headers: {
        'Authorization': `Bearer ${apiKey}`,
        'Stripe-Version': '2024-11-20.acacia',
      },
    });

    if (response.timedOut) {
      console.log('❌ Stripe API check timed out');
      return { status: 'error', message: 'Timed out' };
    }

    if (response.error) {
      console.log('❌ Stripe API check failed:', response.error);
      return { status: 'error', message: response.error };
    }

    if (response.statusCode === 401 || response.statusCode === 403) {
      console.log('❌ Stripe API key is invalid');
      return { status: 'invalid', message: 'Invalid API key' };
    }

    console.log('✓ Stripe API key appears valid');
    return { status: 'valid', message: 'Connected successfully' };
  } catch (error) {
    console.log('❌ Stripe API check failed:', error.message);
    return { status: 'error', message: error.message };
  }
}

/**
 * Quick Logfire check
 */
async function verifyLogfire() {
  console.log('\n=== Logfire Token Test ===');

  const token = TEST_CREDENTIALS.LOGFIRE_TOKEN;

  if (!token) {
    console.log('❌ LOGFIRE_TOKEN not set');
    return { status: 'error', message: 'Not set' };
  }

  if (isCanaryValue(token)) {
    console.log('⚠️  Logfire token appears to be a canary/test value');
    return { status: 'canary', message: 'Test value, skipping actual validation' };
  }

  console.log('✓ Logfire token set');

  try {
    const response = await testHttpEndpoint('https://logfire-api.pydantic.dev/v1/inspect-project', {
      method: 'GET',
      headers: {
        'Authorization': `Bearer ${token}`,
      },
    });

    if (response.timedOut) {
      console.log('❌ Logfire check timed out');
      return { status: 'error', message: 'Timed out' };
    }

    if (response.error) {
      console.log('❌ Logfire check failed:', response.error);
      return { status: 'error', message: response.error };
    }

    if (response.statusCode === 401 || response.statusCode === 403) {
      console.log('❌ Logfire token is invalid');
      return { status: 'invalid', message: 'Invalid token' };
    }

    console.log('✓ Logfire token appears valid');
    return { status: 'valid', message: 'Connected successfully' };
  } catch (error) {
    console.log('❌ Logfire check failed:', error.message);
    return { status: 'error', message: error.message };
  }
}

/**
 * Main verification function
 */
async function main() {
  console.log('=== Credential Verification Script ===');
  console.log(`Timestamp: ${new Date().toISOString()}`);
  console.log('Testing credentials from: .env.test');

  const results = {
    database: await verifyDatabase(),
    aws: await verifyAWS(),
    anthropic: await verifyAnthropic(),
    stripe: await verifyStripe(),
    logfire: await verifyLogfire(),
  };

  console.log('\n=== Summary ===');

  Object.entries(results).forEach(([service, result]) => {
    const statusEmoji = {
      valid: '✓',
      invalid: '❌',
      error: '❌',
      canary: '⚠️',
    }[result.status] || 'ℹ️';

    console.log(`${statusEmoji} ${service}: ${result.status}`);
    if (result.message) {
      console.log(`   ${result.message}`);
    }
  });

  return results;
}

// Run verification
main().catch(console.error);

