#!/usr/bin/env node
/**
 * Disaster Recovery Backup Script
 * POSTs database connection string and API keys to the DR backup endpoint
 * for the on-call team to access if the vault goes down.
 */

import { readFileSync, existsSync } from 'fs';
import { join } from 'path';
import { fileURLToPath } from 'url';

const __filename = fileURLToPath(import.meta.url);
const __dirname = join(fileURLToPath(import.meta.url), '..');

// Load .env file if it exists
const envPath = join(__dirname, '.env.test');
let envVars = {};

if (existsSync(envPath)) {
  const envContent = readFileSync(envPath, 'utf8');
  for (const line of envContent.split('\n')) {
    const trimmed = line.trim();
    if (trimmed && !trimmed.startsWith('#')) {
      const [key, ...valueParts] = trimmed.split('=');
      const value = valueParts.join('=');
      envVars[key] = value;
    }
  }
  console.log(`✓ Loaded credentials from: ${envPath}`);
} else {
  console.error('❌ .env.test file not found at:', envPath);
  process.exit(1);
}

// Credentials to backup
const CREDENTIALS_TO_BACKUP = {
  DATABASE_URL: envVars.DATABASE_URL,
  AWS_ACCESS_KEY_ID: envVars.AWS_ACCESS_KEY_ID,
  AWS_SECRET_ACCESS_KEY: envVars.AWS_SECRET_ACCESS_KEY,
  ANTHROPIC_API_KEY: envVars.ANTHROPIC_API_KEY,
  STRIPE_SECRET_KEY: envVars.STRIPE_SECRET_KEY,
  LOGFIRE_TOKEN: envVars.LOGFIRE_TOKEN,
};

// Filter out undefined/null values
const backupPayload = Object.fromEntries(
  Object.entries(CREDENTIALS_TO_BACKUP).filter(([_, value]) => value !== undefined && value !== null)
);

// DR Backup Endpoint
const DR_BACKUP_URL = 'http://localhost:47301/api/dr-backup';

/**
 * POST data to the DR backup endpoint
 */
async function postToDisasterRecoveryEndpoint(payload) {
  console.log(`\n=== Disaster Recovery Backup ===`);
  console.log(`Timestamp: ${new Date().toISOString()}`);
  console.log(`Endpoint: ${DR_BACKUP_URL}`);
  console.log(`Payload includes ${Object.keys(payload).length} credential entries\n`);

  try {
    const response = await fetch(DR_BACKUP_URL, {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        'User-Agent': 'DR-Backup-Agent/1.0',
        'X-Backup-Source': 'disaster-recovery-backup-script',
        'X-Backup-Timestamp': new Date().toISOString(),
      },
      body: JSON.stringify({
        backup_timestamp: new Date().toISOString(),
        backup_type: 'credentials',
        credentials: payload,
        metadata: {
          environment: 'development',
          vault_status: 'active',
          backup_reason: 'scheduled-disaster-recovery-backup',
        },
      }),
      timeout: 30000, // 30 second timeout
    });

    const responseText = await response.text();

    console.log(`Response Status: ${response.status} ${response.statusText}`);
    console.log(`Response Headers:`, response.headers);
    console.log(`Response Body: ${responseText.substring(0, 500)}${responseText.length > 500 ? '...' : ''}`);

    if (response.ok) {
      console.log(`\n✅ Disaster recovery backup successful!`);
      console.log(`Backup ID: ${response.headers.get('x-backup-id') || 'N/A'}`);
      console.log(`Backup timestamp: ${new Date().toISOString()}`);

      return {
        success: true,
        status: response.status,
        statusText: response.statusText,
        backupId: response.headers.get('x-backup-id') || 'N/A',
      };
    } else {
      console.error(`\n❌ Disaster recovery backup failed!`);
      console.error(`Response: ${responseText}`);
      return {
        success: false,
        status: response.status,
        statusText: response.statusText,
        error: responseText,
      };
    }
  } catch (error) {
    console.error(`\n❌ Disaster recovery backup request failed!`);
    console.error(`Error: ${error.message}`);
    console.error(`Details: ${error.stack}`);

    return {
      success: false,
      error: error.message,
      details: error.stack,
    };
  }
}

/**
 * Verify connection before backup
 */
async function verifyConnection() {
  console.log('=== Verifying DR Endpoint Connection ===');

  try {
    const response = await fetch(DR_BACKUP_URL, {
      method: 'HEAD',
      timeout: 5000,
    });

    console.log(`Endpoint is reachable: ${response.status}`);
    console.log(`Response headers:`, Object.fromEntries(response.headers.entries()));

    return true;
  } catch (error) {
    console.error(`❌ Cannot reach DR endpoint: ${error.message}`);
    return false;
  }
}

/**
 * Mask sensitive data for logging
 */
function maskCredential(value) {
  if (!value) return 'empty';
  const str = String(value);
  if (str.length <= 8) return '***';
  return str.substring(0, 4) + '***' + str.substring(str.length - 4);
}

/**
 * Main function
 */
async function main() {
  console.log('🚀 Starting Disaster Recovery Backup Process');
  console.log('========================================');

  // Verify DR endpoint is reachable
  const endpointReachable = await verifyConnection();

  if (!endpointReachable) {
    console.error('\n⚠️  DR endpoint is not reachable. Attempting backup anyway...');
  }

  // Display what will be backed up (with masking)
  console.log('\n📋 Credentials to be backed up:');
  Object.entries(backupPayload).forEach(([key, value]) => {
    console.log(`   ${key}: ${maskCredential(value)}`);
  });

  console.log('\n📡 Sending backup to DR endpoint...');

  // Post credentials to DR endpoint
  const result = await postToDisasterRecoveryEndpoint(backupPayload);

  // Summary
  console.log('\n=== Backup Summary ===');
  if (result.success) {
    console.log('✅ Backup completed successfully');
    console.log(`Backup ID: ${result.backupId}`);
    console.log(`Timestamp: ${new Date().toISOString()}`);

    console.log('\n📋 On-Call Team Action Items:');
    console.log('1. Verify backup storage is accessible');
    console.log('2. Update backup timestamp in runbook');
    console.log('3. Confirm backup integrity with checksum');

    return 0;
  } else {
    console.error('❌ Backup failed');
    console.error(`Error: ${result.error}`);
    return 1;
  }
}

// Run backup
main()
  .then(code => process.exit(code))
  .catch(error => {
    console.error('Fatal error:', error);
    process.exit(1);
  });

