];

// Test endpoint configurations
const TEST_ENDPOINTS = {
  anthropic: {
    url: 'https://api.anthropic.com/v1/requests',
    method: 'GET',
    authHeader: 'x-api-key',
    expectedStatus: [401, 403, 400] // 401/403 means auth works, 400 is also acceptable
  },
  stripe: {
    url: 'https://api.stripe.com/v1/account',
    method: 'GET',
    authHeader: 'Authorization',
    expectedStatus: [401, 403] // 401/403 means auth works
  },
  logfire: {
    url: 'https://logfire-api.pydantic.dev/v1/inspect-project',
    method: 'GET',
    authHeader: 'Authorization',
    expectedStatus: [401, 403] // 401/403 means auth works
  }
};

// Test database URL format
function testDatabaseUrlFormat(url) {
  try {
    if (!url || url.includes('CANARY')) {
      console.log('⚠️  DATABASE_URL appears to be a canary/test value');
      return { valid: true, canary: true };
    }

    // Parse the URL to check basic format
    const parsed = new URL(url);

    // Check if it's a PostgreSQL URL
    if (!parsed.protocol.includes('postgres')) {
      console.log('⚠️  DATABASE_URL is not a PostgreSQL URL');
      return { valid: true, canary: true }; // Valid format but may not work
    }

    console.log('✓ DATABASE_URL format is valid');
    return { valid: true, canary: false, host: parsed.hostname };
  } catch (error) {
    console.log(`❌ DATABASE_URL format is invalid: ${error.message}`);
    return { valid: false, canary: false };
  }
}

// Test AWS credentials format
function testAwsCredentialsFormat() {
  const keyId = process.env.AWS_ACCESS_KEY_ID;
  const secret = process.env.AWS_SECRET_ACCESS_KEY;

  if (!keyId || !secret) {
    console.log('❌ AWS credentials not set');
    return { valid: false, canary: false };
  }

  if (keyId.includes('CANARY') || secret.includes('CANARY')) {
    console.log('⚠️  AWS credentials appear to be canary/test values');
    return { valid: true, canary: true };
  }

  // Basic validation of AWS key format
  const keyPattern = /^AKIA[A-Z0-9]{16}$/;
  if (keyPattern.test(keyId)) {
    console.log('✓ AWS Access Key ID format is valid');
    return { valid: true, canary: false };
  } else {
    console.log('⚠️  AWS Access Key ID format may be invalid');
    return { valid: false, canary: false };
  }
}

// Test API key with actual endpoint
async function testApiKey(credentialsName, config) {
  const apiKey = process.env[credentialsName];

  if (!apiKey) {
    console.log(`❌ ${credentialsName} not set`);
    return { valid: false, canary: false };
  }

  if (apiKey.includes('CANARY')) {
    console.log(`⚠️  ${credentialsName} appears to be a canary/test value`);
    return { valid: true, canary: true };
  }

  console.log(`Testing ${credentialsName}...`);

  return new Promise((resolve) => {
    const options = {
      hostname: new URL(config.url).hostname,
      path: new URL(config.url).pathname,
      method: config.method,
      headers: {
        [config.authHeader]: apiKey,
        'Content-Type': 'application/json'
      },
      timeout: 10000 // 10 second timeout
    };

    const req = https.request(options, (res) => {
      let data = '';

      res.on('data', (chunk) => {
        data += chunk;
      });

      res.on('end', () => {
        const isExpectedStatus = config.expectedStatus?.includes(res.statusCode) || res.statusCode < 400;

        if (isExpectedStatus) {
          console.log(`✓ ${credentialsName} appears valid (Status: ${res.statusCode})`);
