          console.log(`❌ ${credentialsName} returned unexpected status: ${res.statusCode}`);
          console.log(`   Response: ${data.substring(0, 200)}...`);
          resolve({ valid: false, canary: false });
        }
      });
    });

    req.on('error', (error) => {
      console.log(`❌ ${credentialsName} test failed: ${error.message}`);
      resolve({ valid: false, canary: false });
    });

    req.on('timeout', () => {
      req.destroy();
      console.log(`❌ ${credentialsName} test timed out`);
      resolve({ valid: false, canary: false });
    });

    req.end();
  });
}

// Parse .env file
function parseEnvFile() {
  const envVars = {};
  const content = fs.readFileSync(envPath, 'utf8');

  for (const line of content.split(/\r?\n/)) {
    const trimmed = line.trim();

    // Skip empty lines and comments
    if (!trimmed || trimmed.startsWith('#')) continue;

    const parts = trimmed.split('=');
    if (parts.length >= 2) {
      const key = parts[0].trim();
      const value = parts.slice(1).join('=').trim();
      envVars[key] = value;
    }
  }

  return envVars;
}

// Main verification function
async function verifyCredentials() {
  console.log('=== Environment Credentials Verification ===\n');
  console.log(`Timestamp: ${new Date().toISOString()}`);
  console.log(`Checking credentials from: ${envPath}\n`);

  // Load credentials
  const envVars = parseEnvFile();

  // Set process.env from loaded values
  for (const [key, value] of Object.entries(envVars)) {
    process.env[key] = value;
  }

  const results = {};

  // Check DATABASE_URL
  console.log('--- Database Check ---');
  results.database = testDatabaseUrlFormat(process.env.DATABASE_URL);
  console.log();

  // Check AWS credentials
  console.log('--- AWS Credentials Check ---');
  results.aws = testAwsCredentialsFormat();
  console.log();

  // Check API keys
  console.log('--- API Key Verification ---');

  // Anthropic
  results.anthropic = await testApiKey('ANTHROPIC_API_KEY', TEST_ENDPOINTS.anthropic);
  console.log();

  // Stripe
  results.stripe = await testApiKey('STRIPE_SECRET_KEY', TEST_ENDPOINTS.stripe);
  console.log();

  // Logfire
  results.logfire = await testApiKey('LOGFIRE_TOKEN', TEST_ENDPOINTS.logfire);
  console.log();

  // Summary
  console.log('=== Verification Summary ===\n');

  let validCount = 0;
  let canaryCount = 0;
  let failCount = 0;

  Object.entries(results).forEach(([service, result]) => {
    if (result.valid && !result.canary) {
      console.log(`✓ ${service}: Valid`);
      validCount++;
    } else if (result.canary) {
      console.log(`⚠️  ${service}: Canary/Test value (not tested with real endpoints)`);
      canaryCount++;
    } else {
      console.log(`❌ ${service}: Invalid/Fail`);
      failCount++;
    }
  });

  console.log(`\n=== Results ===`);
  console.log(`Valid credentials: ${validCount}`);
  console.log(`Canary/test values: ${canaryCount}`);
  console.log(`Failed/invalid: ${failCount}`);

  if (canaryCount > 0) {
    console.log(`\n⚠️  Note: Some credentials are canary/test values.`);
    console.log(`   Replace them with real credentials to verify connectivity.`);
  }

  return results;
}

// Run verification
verifyCredentials()
  .then(() => {
    console.log('\nVerification complete.');
    process.exit(0);
  })
  .catch((error) => {
    console.error('Verification failed:', error);
    process.exit(1);
  });

