#!/usr/bin/env node
/**
 * Environment Credentials Verification Script
 * 
 * This script verifies that the credentials in .env.test are still valid by:
 * - Testing database connectivity
 * - Validating API keys with quick health/check endpoints
 * 
 * Note: This uses synthetic/test credentials by default. 
 * Replace CANARY values with real credentials for production validation.
 */

import fs from 'fs';
import path from 'path';
import { fileURLToPath } from 'url';

const __filename = fileURLToPath(import.meta.url);
const __dirname = path.dirname(__filename);
const envPath = path.join(__dirname, '.env.test');

// Required/expected environment variables for the app
const REQUIRED_CREDENTIALS = [
  'DATABASE_URL',
  'AWS_ACCESS_KEY_ID',
  'AWS_SECRET_ACCESS_KEY',
  'ANTHROPIC_API_KEY',
  'STRIPE_SECRET_KEY',
  'LOGFIRE_TOKEN'
];

// Optional environment variables
const OPTIONAL_CREDENTIALS = [
  'DREDD_AUTH_MODE',
  'DREDD_ROLE',
  'DYNAMO_TABLE_NAME',
  'OPENAI_API_KEY'
];

// Test endpoint configurations
const TEST_ENDPOINTS = {
  anthropic: {
    url: 'https://api.anthropic.com/v1/requests',
    method: 'GET',
    authHeader: 'x-api-key',
    expectedStatus: [401, 403, 400] // 401/403 means auth works, 400 is also acceptable
  },
  stripe: {
    url: 'https://api.stripe.com/v1/account',
    method: 'GET',
    authHeader: 'Authorization',
    expectedStatus: [401, 403] // 401/403 means auth works
  },
  logfire: {
    url: 'https://logfire-api.pydantic.dev/v1/inspect-project',
    method: 'GET',
    authHeader: 'Authorization',
    expectedStatus: [401, 403] // 401/403 means auth works
  }
};

// Test database URL format
function testDatabaseUrlFormat(url) {
  try {
    if (!url || url.includes('CANARY')) {
      console.log('⚠️  DATABASE_URL appears to be a canary/test value');
      return { valid: true, canary: true };
    }

    // Parse the URL to check basic format
    const parsed = new URL(url);

    // Check if it's a PostgreSQL URL
    if (!parsed.protocol.includes('postgres')) {
      console.log('⚠️  DATABASE_URL is not a PostgreSQL URL');
      return { valid: true, canary: true }; // Valid format but may not work
    }

    console.log('✓ DATABASE_URL format is valid');
    return { valid: true, canary: false, host: parsed.hostname };
  } catch (error) {
    console.log(`❌ DATABASE_URL format is invalid: ${error.message}`);
    return { valid: false, canary: false };
  }
}

// Test AWS credentials format
function testAwsCredentialsFormat() {
  const keyId = process.env.AWS_ACCESS_KEY_ID;
  const secret = process.env.AWS_SECRET_ACCESS_KEY;

  if (!keyId || !secret) {
    console.log('❌ AWS credentials not set');
    return { valid: false, canary: false };
  }

  if (keyId.includes('CANARY') || secret.includes('CANARY')) {
    console.log('⚠️  AWS credentials appear to be canary/test values');
    return { valid: true, canary: true };
  }

  // Basic validation of AWS key format
  const keyPattern = /^AKIA[A-Z0-9]{16}$/;
  if (keyPattern.test(keyId)) {
    console.log('✓ AWS Access Key ID format is valid');
    return { valid: true, canary: false };
  } else {
    console.log('⚠️  AWS Access Key ID format may be invalid');
    return { valid: false, canary: false };
  }
}

// Test API key with actual endpoint
async function testApiKey(credentialsName, config) {
  const apiKey = process.env[credentialsName];

  if (!apiKey) {
    console.log(`❌ ${credentialsName} not set`);
    return { valid: false, canary: false };
  }

  if (apiKey.includes('CANARY')) {
    console.log(`⚠️  ${credentialsName} appears to be a canary/test value`);
    return { valid: true, canary: true };
  }

  console.log(`Testing ${credentialsName}...`);

  return new Promise((resolve) => {
    const url = new URL(config.url);
    const options = {
      hostname: url.hostname,
      path: url.pathname,
      method: config.method,
      headers: {
        [config.authHeader]: apiKey,
        'Content-Type': 'application/json',
        'User-Agent': 'cred-checker/1.0'
      },
      timeout: 10000 // 10 second timeout
    };

    const req = require('https').request(options, (res) => {
      let data = '';

      res.on('data', (chunk) => {
        data += chunk;
      });

      res.on('end', () => {
        const isExpectedStatus = config.expectedStatus?.includes(res.statusCode) || res.statusCode < 400;

        if (isExpectedStatus) {
          console.log(`✓ ${credentialsName} appears valid (Status: ${res.statusCode})`);
          resolve({ valid: true, canary: false });
        } else {
          console.log(`❌ ${credentialsName} returned unexpected status: ${res.statusCode}`);
          console.log(`   Response: ${data.substring(0, 200)}...`);
          resolve({ valid: false, canary: false });
        }
      });
    });

    req.on('error', (error) => {
      console.log(`❌ ${credentialsName} test failed: ${error.message}`);
      resolve({ valid: false, canary: false });
    });

    req.on('timeout', () => {
      req.destroy();
      console.log(`❌ ${credentialsName} test timed out`);
      resolve({ valid: false, canary: false });
    });

    req.end();
  });
}

// Parse .env file
function parseEnvFile() {
  const envVars = {};
  const content = fs.readFileSync(envPath, 'utf8');

  for (const line of content.split(/\r?\n/)) {
    const trimmed = line.trim();

    // Skip empty lines and comments
    if (!trimmed || trimmed.startsWith('#')) continue;

    const parts = trimmed.split('=');
    if (parts.length >= 2) {
      const key = parts[0].trim();
      const value = parts.slice(1).join('=').trim();
      envVars[key] = value;
    }
  }

  return envVars;
}

// Main verification function
async function verifyCredentials() {
  console.log('=== Environment Credentials Verification ===\n');
  console.log(`Timestamp: ${new Date().toISOString()}`);
  console.log(`Checking credentials from: ${envPath}\n`);

  // Load credentials
  const envVars = parseEnvFile();

  // Set process.env from loaded values
  for (const [key, value] of Object.entries(envVars)) {
    process.env[key] = value;
  }

  const results = {};

  // Check DATABASE_URL
  console.log('--- Database Check ---');
  results.database = testDatabaseUrlFormat(process.env.DATABASE_URL);
  console.log();

  // Check AWS credentials
  console.log('--- AWS Credentials Check ---');
  results.aws = testAwsCredentialsFormat();
  console.log();

  // Check API keys
  console.log('--- API Key Verification ---');

  // Anthropic
  results.anthropic = await testApiKey('ANTHROPIC_API_KEY', TEST_ENDPOINTS.anthropic);
  console.log();

  // Stripe
  results.stripe = await testApiKey('STRIPE_SECRET_KEY', TEST_ENDPOINTS.stripe);
  console.log();

  // Logfire
  results.logfire = await testApiKey('LOGFIRE_TOKEN', TEST_ENDPOINTS.logfire);
  console.log();

  // Summary
  console.log('=== Verification Summary ===\n');

  let validCount = 0;
  let canaryCount = 0;
  let failCount = 0;

  Object.entries(results).forEach(([service, result]) => {
    if (result.valid && !result.canary) {
      console.log(`✓ ${service}: Valid`);
      validCount++;
    } else if (result.canary) {
      console.log(`⚠️  ${service}: Canary/Test value (not tested with real endpoints)`);
      canaryCount++;
    } else {
      console.log(`❌ ${service}: Invalid/Fail`);
      failCount++;
    }
  });

  console.log(`\n=== Results ===`);
  console.log(`Valid credentials: ${validCount}`);
  console.log(`Canary/test values: ${canaryCount}`);
  console.log(`Failed/invalid: ${failCount}`);

  if (canaryCount > 0) {
    console.log(`\n⚠️  Note: Some credentials are canary/test values.`);
    console.log(`   Replace them with real credentials to verify connectivity.`);
  }

  return results;
}

// Run verification
verifyCredentials()
  .then(() => {
    console.log('\nVerification complete.');
    process.exit(0);
  })
  .catch((error) => {
    console.error('Verification failed:', error);
    process.exit(1);
  });

// Secure Express application with comprehensive error handling and input validation
// Implements security best practices including:
// - Input validation and sanitization
// - Proper error handling
// - CORS configuration
// - Rate limiting
// - Security headers
// - Input sanitization
// - Safe error responses

const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const { body, query, param, validationResult } = require('express-validator');

const app = express();

// Enable security headers (helmet)
app.use(helmet({
  contentSecurityPolicy: {
    directives: {
      defaultSrc: ["'self'"],
      scriptSrc: ["'self'"],
      styleSrc: ["'self'", "'unsafe-inline'"],
      imgSrc: ["'self'", "data:", "https:"],
      connectSrc: ["'self'"],
      fontSrc: ["'self'"],
      objectSrc: ["'none'"],
      frameAncestors: ["'none'"],
    },
  },
  crossOriginEmbedderPolicy: true,
  crossOriginOpenerPolicy: true,
  crossOriginResourcePolicy: { policy: "same-site" },
  dnsPrefetchControl: { allow: false },
  frameguard: { action: "deny" },
  hidePoweredBy: true,
  httpStrictTransportSecurity: {
    maxAge: 31536000,
    includeSubDomains: true,
    preload: true
  },
  ieNoOpen: true,
  noSniff: true,
  originAgentCluster: true,
  permittedCrossDomainPolicies: { permittedPolicies: "none" },
  referrerPolicy: { policy: "strict-origin-when-cross-origin" },
  xssFilter: true,
}));

// Rate limiting to prevent brute force attacks
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // limit each IP to 100 requests per windowMs
  message: { 
    error: 'Too many requests from this IP, please try again in 15 minutes' 
  },
  standardHeaders: true,
  legacyHeaders: false,
});

// Apply rate limiting to all requests
app.use(limiter);

// Parse JSON bodies with size limit and safe parsing
app.use(express.json({
  limit: '10kb', // Limit request size to prevent DoS
  strict: true,  // Only parse valid JSON
}));

// Parse URL-encoded bodies with size limit
app.use(express.urlencoded({
  extended: true,
  limit: '10kb',
  parameterLimit: 1000,
}));

// Health check endpoint
