#!/usr/bin/env node
/**
 * Credential Verification Script
 * 
 * Tests the validity of credentials stored in .env.test by:
 * - Attempting database connectivity
 * - Making authenticated API calls to verify keys
 * - Only reporting success/failure, NOT exposing credentials
 */

const fs = require('fs');
