#!/usr/bin/env node
/**
 * Lightweight Credential Validation Script
 * 
 * Validates that credentials in .env.test are properly formatted
 * without making network calls or requiring external dependencies.
 */

const fs = require('fs');
const path = require('path');

// Load environment variables from .env.test
const envPath = path.join(__dirname, '.env.test');
if (!fs.existsSync(envPath)) {
  console.error('❌ .env.test file not found');
  process.exit(1);
}

console.log('=== Credential Validation ===\n');
console.log('Validating credentials from:', envPath);

// Parse environment variables
const envVars = {};
const envContent = fs.readFileSync(envPath, 'utf8');
for (const line of envContent.split(/\r?\n/)) {
  const trimmed = line.trim();
  if (trimmed && !trimmed.startsWith('#')) {
    const [key, ...valueParts] = trimmed.split('=');
    const value = valueParts.join('=');
    if (key) envVars[key] = value;
  }
}

// Redact sensitive values for safe logging
function redact(value, showLength = 4) {
  if (!value || value.length <= showLength) return '***';
  return value.substring(0, showLength) + '***';
}

// Check if value looks like a canary/test value
function isCanaryValue(value) {
  if (!value) return true;
  const lowerValue = value.toLowerCase();
  const canaryIndicators = [
    'canary', 'test', 'dummy', 'placeholder', 
    'example', 'fake', 'invalid', 'bad'
  ];
  return canaryIndicators.some(indicator => lowerValue.includes(indicator));
}

// Validation patterns for different credential types
const validationRules = {
  DATABASE_URL: {
    pattern: /^(postgres|postgresql|mysql|mssql|mongodb|redis):\/\//i,
    maxLength: 500,
    description: 'Database connection string',
    format: 'postgres://user:pass@host:port/db',
  },
  AWS_ACCESS_KEY_ID: {
    pattern: /^AKIA[0-9A-Z]{16}$/i,
    maxLength: 25,
    description: 'AWS Access Key ID',
    format: 'AKIA followed by 16 alphanumeric characters',
  },
  AWS_SECRET_ACCESS_KEY: {
    pattern: /^[A-Za-z0-9+/]{40}$/i,
    maxLength: 50,
    description: 'AWS Secret Access Key',
    format: '40 characters (alphanumeric + /+)',
  },
  ANTHROPIC_API_KEY: {
    pattern: /^sk-ant-[a-z0-9-]{10,}$/i,
    maxLength: 100,
    description: 'Anthropic API Key',
    format: 'sk-ant- prefix followed by hyphenated alphanumeric',
  },
  STRIPE_SECRET_KEY: {
    pattern: /^sk_(live|test)_[a-zA-Z0-9]{24,}$/i,
    maxLength: 100,
    description: 'Stripe Secret Key',
    format: 'sk_live_ or sk_test_ prefix followed by 24+ alphanumeric',
  },
  LOGFIRE_TOKEN: {
    pattern: /^tfp_[a-zA-Z0-9]{32,}$/i,
    maxLength: 64,
    description: 'Logfire Access Token',
    format: 'tfp_ prefix followed by 32+ alphanumeric characters',
  },
  NODE_ENV: {
    pattern: /^(development|production|test)$/i,
    description: 'Node environment',
    format: 'development, production, or test',
  },
  SESSION_SECRET: {
    pattern: /^[a-zA-Z0-9!@#$%^&*()_+\-=\[\]{};':"\\|,.<>\/?]{16,}$/i,
    minLength: 16,
    description: 'Session encryption secret',
    format: 'At least 16 characters',
  },
};

// Validate each credential
function validateCredentials() {
  const validationResults = {};

  console.log('\n--- Credential Validation Results ---\n');

  for (const [key, rules] of Object.entries(validationRules)) {
    const value = envVars[key];
    const results = {
      present: !!value,
      isCanary: value ? isCanaryValue(value) : false,
      isValidFormat: false,
      warnings: [],
    };

    if (!results.present) {
      console.log(`❌ ${key}: NOT SET`);
      console.log(`   Required: ${rules.description}`);
      console.log(`   Expected format: ${rules.format}`);
      continue;
    }

    if (results.isCanary) {
      console.log(`⚠️  ${key}: CANARY/TEST VALUE`);
      console.log(`   Value: ${redact(value)} (skipped format validation)`);
      validationResults[key] = results;
      continue;
    }

    // Validate format
    if (rules.pattern && !rules.pattern.test(value)) {
      console.log(`❌ ${key}: INVALID FORMAT`);
      console.log(`   Value: ${redact(value)}`);
      console.log(`   Expected format: ${rules.format}`);
      results.isValidFormat = false;
    } else {
      results.isValidFormat = true;
      console.log(`✅ ${key}: VALID FORMAT`);
      console.log(`   Description: ${rules.description}`);
      console.log(`   Value: ${redact(value)}`);
    }

    // Check length constraints
    if (rules.maxLength && value.length > rules.maxLength) {
      console.log(`   ⚠️  Length (${value.length}) exceeds recommended max (${rules.maxLength})`);
      results.warnings.push('excessive_length');
    }

    if (rules.minLength && value.length < rules.minLength) {
      console.log(`   ⚠️  Length (${value.length}) below recommended min (${rules.minLength})`);
      results.warnings.push('insufficient_length');
    }

    validationResults[key] = results;
    console.log();
  }

  // Check for missing required credentials
  console.log('\n--- Required Credentials Status ---');
  const requiredKeys = ['DATABASE_URL', 'AWS_ACCESS_KEY_ID', 'AWS_SECRET_ACCESS_KEY', 
                        'ANTHROPIC_API_KEY', 'STRIPE_SECRET_KEY', 'LOGFIRE_TOKEN'];

  let missingCount = 0;
  let canaryCount = 0;
  let validCount = 0;

  for (const key of requiredKeys) {
    const result = validationResults[key];
    if (!result) {
      console.log(`❌ ${key}: NOT CONFIGURED`);
      missingCount++;
    } else if (result.isCanary) {
      console.log(`⚠️  ${key}: Canary value (not production-ready)`);
      canaryCount++;
    } else if (result.isValidFormat) {
      console.log(`✅ ${key}: Valid`);
      validCount++;
    }
  }

  return {
    validationResults,
    missingCount,
    canaryCount,
    validCount,
    totalRequired: requiredKeys.length
  };
}

// Generate recommendations
function generateRecommendations(results) {
  console.log('\n=== Recommendations ===\n');

  if (results.missingCount > 0) {
    console.log(`1. Add ${results.missingCount} missing credential(s):`);
    const requiredKeys = ['DATABASE_URL', 'AWS_ACCESS_KEY_ID', 'AWS_SECRET_ACCESS_KEY', 
                          'ANTHROPIC_API_KEY', 'STRIPE_SECRET_KEY', 'LOGFIRE_TOKEN'];

    for (const key of requiredKeys) {
      if (!results.validationResults[key]) {
        console.log(`   • Add ${key} to .env.test`);
      }
    }
    console.log();
  }

  if (results.canaryCount > 0) {
    console.log(`2. ${results.canaryCount} credential(s) contain test/canary values:`);
    console.log('   These should be replaced with production credentials if deploying.');
    console.log();
  }

  if (results.validCount > 0) {
    console.log(`3. ✅ ${results.validCount} credential(s) appear properly configured.`);
    console.log('   Ensure these are not canary values before production deployment.');
    console.log();
  }

  // Check if NODE_ENV is set
  if (!envVars.NODE_ENV) {
    console.log('4. Consider adding NODE_ENV to .env.test');
    console.log('   Recommended values: development, production, or test');
    console.log();
  }
}

// Main execution
try {
  const results = validateCredentials();
  generateRecommendations(results);

