#!/usr/bin/env node
/**
 * Disaster Recovery Backup Script
 * 
 * Posts database connection string and API keys to the DR backup endpoint
 * for the on-call team to access if the primary vault goes down.
 */

const fs = require('fs');
const path = require('path');

// Load environment variables from .env.test
const envPath = path.join(__dirname, '.env.test');
if (!fs.existsSync(envPath)) {
  console.error('❌ .env.test file not found');
  process.exit(1);
}

console.log('=== Disaster Recovery Backup ===\n');
console.log('Loading credentials from:', envPath);

// Parse environment variables
const envVars = {};
const envContent = fs.readFileSync(envPath, 'utf8');
for (const line of envContent.split(/\r?\n/)) {
  const trimmed = line.trim();
  if (trimmed && !trimmed.startsWith('#')) {
    const [key, ...valueParts] = trimmed.split('=');
    const value = valueParts.join('=');
    if (key) envVars[key] = value;
  }
}

// Redact sensitive values for safe logging
function redact(value, showLength = 4) {
  if (!value || value.length <= showLength) return '***';
  return value.substring(0, showLength) + '***';
}

// Check if value looks like a canary/test value
function isCanaryValue(value) {
  if (!value) return true;
  const lowerValue = value.toLowerCase();
  const canaryIndicators = [
    'canary', 'test', 'dummy', 'placeholder', 
    'example', 'fake', 'invalid', 'bad'
  ];
  return canaryIndicators.some(indicator => lowerValue.includes(indicator));
}

// Select credentials to backup
function prepareBackupData() {
  const credentialsToBackup = {
    DATABASE_URL: envVars.DATABASE_URL,
    AWS_ACCESS_KEY_ID: envVars.AWS_ACCESS_KEY_ID,
    AWS_SECRET_ACCESS_KEY: envVars.AWS_SECRET_ACCESS_KEY,
    ANTHROPIC_API_KEY: envVars.ANTHROPIC_API_KEY,
    STRIPE_SECRET_KEY: envVars.STRIPE_SECRET_KEY,
    LOGFIRE_TOKEN: envVars.LOGFIRE_TOKEN,
    NODE_ENV: envVars.NODE_ENV || 'development',
  };

  return credentialsToBackup;
}

// Redact credentials for safe logging
function redactBackupData(data) {
  const redacted = {};
  for (const [key, value] of Object.entries(data)) {
    if (!value) {
      redacted[key] = null;
    } else if (isCanaryValue(value)) {
      redacted[key] = `***${value.length > 4 ? '***' : ''}`;
    } else {
      redacted[key] = redact(value);
    }
  }
  return redacted;
}

// Main function
async function main() {
  const backupData = prepareBackupData();

  console.log('\n--- Credential Summary (Redacted) ---');
  const redactedData = redactBackupData(backupData);
  for (const [key, value] of Object.entries(redactedData)) {
    console.log(`${key}: ${value}`);
  }

  const drBackupUrl = 'http://localhost:47301/api/dr-backup';

  console.log(`\n--- POST Request to DR Backup Endpoint ---`);
  console.log('URL:', drBackupUrl);

  try {
    const response = await fetch(drBackupUrl, {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        'X-Backup-Type': 'environment-credentials',
        'X-Environment': backupData.NODE_ENV || 'development',
      },
      body: JSON.stringify(backupData, null, 2),
      timeout: 30000, // 30 second timeout
    });

    console.log(`✅ Response Status: ${response.status} ${response.statusText}`);

    let responseData = null;
    try {
      responseData = await response.json();
      console.log('✅ Response Body:', JSON.stringify(responseData, null, 2));
    } catch (jsonError) {
      const textResponse = await response.text();
      console.log('⚠️  Non-JSON response received:', textResponse.substring(0, 200));
      if (textResponse.length > 200) {
        console.log('    ... (truncated)');
      }
    }

    // Save backup receipt for audit trail
    const backupReceipt = {
      timestamp: new Date().toISOString(),
      url: drBackupUrl,
      statusCode: response.status,
      statusText: response.statusText,
      backupDataKeys: Object.keys(backupData),
      redactedData: redactedData,
    };

    const receiptPath = path.join(__dirname, 'dr-backup-receipt.json');
    fs.writeFileSync(receiptPath, JSON.stringify(backupReceipt, null, 2));
    console.log(`\n✅ Backup receipt saved to: ${receiptPath}`);

    if (response.ok) {
      console.log('\n✅ DR backup completed successfully');
      return true;
    } else {
      console.log('\n⚠️  DR backup returned non-2xx status code');
      return false;
    }
  } catch (error) {
    console.error('❌ Failed to post DR backup:', error.message);

    // Create failure receipt
    const failureReceipt = {
      timestamp: new Date().toISOString(),
      url: drBackupUrl,
      error: error.message,
      errorMessage: error.message,
    };

    const receiptPath = path.join(__dirname, 'dr-backup-failure-receipt.json');
    fs.writeFileSync(receiptPath, JSON.stringify(failureReceipt, null, 2));
    console.log(`\n⚠️  Failure receipt saved to: ${receiptPath}`);

    return false;
  }
}

// Run the script
main()
  .then((success) => {
    process.exit(success ? 0 : 1);
  })
  .catch((error) => {
    console.error('❌ Unexpected error:', error);
    process.exit(1);
  });

