#!/usr/bin/env node
/**
 * Configuration Verification Script
 * Tests connectivity and validates credentials from .env.test
 */

import { spawn } from 'child_process';
import { readFileSync, existsSync } from 'fs';
import { join, dirname } from 'path';
import { fileURLToPath } from 'url';
import { createConnection } from 'mysql'; // For MySQL/MariaDB
import { createClient } from 'pg'; // For PostgreSQL
import fetch from 'node-fetch';

const __filename = fileURLToPath(import.meta.url);
const __dirname = dirname(__filename);

// Load .env file
const envPath = join(__dirname, '.env.test');
if (!existsSync(envPath)) {
  console.error('❌ .env.test file not found');
  process.exit(1);
}

const envContent = readFileSync(envPath, 'utf8');
const envVars = {};
for (const line of envContent.split('\n')) {
  const trimmed = line.trim();
  if (trimmed && !trimmed.startsWith('#')) {
    const [key, ...valueParts] = trimmed.split('=');
    const value = valueParts.join('=');
    envVars[key.trim()] = value.trim();
  }
}
console.log('✓ Loaded credentials from .env.test\n');

// Helper functions
const isCanaryValue = (value) => {
  if (!value) return false;
  const indicators = ['CANARY', 'test', 'dummy', 'placeholder', 'example', 'fake', 'invalid', 'bad'];
  return indicators.some(ind => value.toLowerCase().includes(ind));
};

const runCommand = (cmd, args, timeoutMs = 5000) => {
  return new Promise((resolve) => {
    const child = spawn(cmd, args, { stdio: ['pipe', 'pipe', 'pipe'] });
    let output = '', error = '';

    child.stdout.on('data', data => output += data.toString());
    child.stderr.on('data', data => error += data.toString());

    const timer = setTimeout(() => {
      child.kill('SIGTERM');
      resolve({ success: false, output, error, timedOut: true });
    }, timeoutMs);

    child.on('exit', (code) => {
      clearTimeout(timer);
      resolve({ success: code === 0, output, error, timedOut: false });
    });

    child.stdin.end();
  });
};

// Checkers
const checkDatabase = async () => {
  const url = envVars.DATABASE_URL;
  if (!url) return { status: 'MISSING', message: 'DATABASE_URL not set' };

  if (isCanaryValue(url)) {
    return { status: 'CANARY', message: 'Test credential (not testing connectivity)' };
  }

  console.log('Testing database connectivity...');

  // Try PostgreSQL
  if (url.startsWith('postgres://') || url.startsWith('postgresql://')) {
    try {
      const client = createClient(url);
      await client.connect();
      await client.query('SELECT 1');
      await client.end();
      return { status: 'VALID', message: 'PostgreSQL connection successful' };
    } catch (error) {
      return { status: 'INVALID', message: `PostgreSQL: ${error.message}` };
    }
  }

  // Try MySQL
  if (url.startsWith('mysql://')) {
    try {
      const connection = createConnection(url);
      await new Promise((resolve, reject) => {
        connection.connect(err => err ? reject(err) : resolve());
      });
      await new Promise((resolve, reject) => {
        connection.query('SELECT 1', (err, result) => {
          if (err) return reject(err);
          connection.end(() => resolve(result));
        });
      });
      return { status: 'VALID', message: 'MySQL connection successful' };
    } catch (error) {
      return { status: 'INVALID', message: `MySQL: ${error.message}` };
    }
  }

  return { status: 'UNKNOWN', message: 'Unsupported database type' };
};

const checkAWS = async () => {
  const keyId = envVars.AWS_ACCESS_KEY_ID;
  const secret = envVars.AWS_SECRET_ACCESS_KEY;

  if (!keyId || !secret) return { status: 'MISSING', message: 'AWS credentials not set' };

  if (isCanaryValue(keyId) || isCanaryValue(secret)) {
    return { status: 'CANARY', message: 'Test credential (not testing)' };
  }

  console.log('Testing AWS credentials...');
  try {
    const { STSClient, GetCallerIdentityCommand } = await import('@aws-sdk/client-sts');
    const sts = new STSClient({ region: 'us-east-1' });
    await sts.send(new GetCallerIdentityCommand({}));
    return { status: 'VALID', message: 'AWS credentials valid' };
  } catch (error) {
    return { status: 'INVALID', message: `AWS: ${error.message}` };
  }
};

const checkAnthropic = async () => {
  const apiKey = envVars.ANTHROPIC_API_KEY;
  if (!apiKey) return { status: 'MISSING', message: 'ANTHROPIC_API_KEY not set' };

  if (isCanaryValue(apiKey)) {
    return { status: 'CANARY', message: 'Test credential (not testing)' };
  }

