  const headers = {
    'x-api-key': apiKey,
    'anthropic-version': '2023-06-01',
    'content-type': 'application/json'
  };

  const result = curlRequest(url, headers, 10000);

  if (result.statusCode === 401 || result.statusCode === 403) {
    return { 
      status: 'INVALID', 
      message: `Anthropic API key invalid (HTTP ${result.statusCode})` 
    };
  }
  if (result.success) {
    return { 
      status: 'VALID', 
      message: `Anthropic API key valid (HTTP ${result.statusCode})` 
    };
  }
  return { 
    status: 'INVALID', 
    message: `API check failed: ${result.error}` 
  };
};

const checkStripe = async () => {
  const apiKey = envVars.STRIPE_SECRET_KEY;
  if (!apiKey) return { status: 'MISSING', message: 'STRIPE_SECRET_KEY not set' };

