import { readFileSync, existsSync } from 'fs';
import { join, dirname } from 'path';
import { fileURLToPath } from 'url';

const __filename = fileURLToPath(import.meta.url);
const __dirname = dirname(__filename);

// Load .env file
const envPath = join(__dirname, '.env.test');
if (!existsSync(envPath)) {
  console.error('❌ .env.test file not found');
  process.exit(1);
}

const envContent = readFileSync(envPath, 'utf8');
const envVars = {};
for (const line of envContent.split('\n')) {
  const trimmed = line.trim();
  if (trimmed && !trimmed.startsWith('#')) {
    const [key, ...valueParts] = trimmed.split('=');
    const value = valueParts.join('=');
    envVars[key.trim()] = value.trim();
  }
}

console.log('=== Configuration Verification ===\n');
console.log(`Timestamp: ${new Date().toISOString()}`);
console.log(`Environment file: ${envPath}`);
console.log('──────────────────────────────────────\n');

// Helper functions
const isCanaryValue = (value) => {
  if (!value || typeof value !== 'string') return false;
  const indicators = ['canary', 'test', 'dummy', 'placeholder', 'example', 'fake', 'invalid', 'bad'];
  const lowerValue = value.toLowerCase();
  return indicators.some(ind => {
    // Check if the indicator appears as a separate word or in a known canary pattern
    if (ind === 'canary') {
      return lowerValue.includes('canary');
    }
    return lowerValue.includes(ind);
  });
};

const runCommand = (cmd, timeout = 10000) => {
  try {
    const output = execSync(cmd, { 
      encoding: 'utf8',
      timeout: timeout,
      stdio: ['ignore', 'pipe', 'pipe']
    });
    return { success: true, output: output.trim() };
  } catch (error) {
    return { 
      success: false, 
      error: error.message || error.stderr?.toString() || error.stdout?.toString() || 'Unknown error' 
    };
  }
};

const curlRequest = (url, headers = {}, timeout = 10000) => {
  let curlCmd = `curl -s -w "\\n%{http_code}" -o /dev/null -f "${url}"`;

  for (const [key, value] of Object.entries(headers)) {
    curlCmd += ` -H "${key}: ${value}"`;
  }

  const result = runCommand(curlCmd, timeout);
  if (result.success) {
    // Parse the HTTP code from output
    const statusCode = result.output.split('\n').pop();
    result.statusCode = parseInt(statusCode);
    result.success = statusCode >= 200 && statusCode < 400;
  }
  return result;
};

// Checkers
const checkDatabase = async () => {
  const url = envVars.DATABASE_URL;
  if (!url) return { status: 'MISSING', message: 'DATABASE_URL not set' };

  if (isCanaryValue(url)) {
    return { 
      status: 'CANARY', 
      message: 'Test credential (skipping connectivity test)',
      details: url.replace(/\/\/.*@/, '://***@') 
    };
  }

  console.log('Testing database connectivity...');

  // Check if psql is available
  const psqlResult = runCommand('which psql');
  if (!psqlResult.success) {
    return { 
      status: 'SKIP', 
      message: 'psql CLI not available, cannot verify database connection' 
    };
  }

  // Try to connect with psql
  const dbResult = runCommand(`psql "${url}" -c "SELECT 1" 2>&1`, 10000);
  if (dbResult.success) {
    return { 
      status: 'VALID', 
      message: 'PostgreSQL connection successful' 
    };
  } else {
    return { 
      status: 'INVALID', 
      message: `Database connection failed: ${dbResult.error}` 
    };
  }
};

const checkAWS = async () => {
  const keyId = envVars.AWS_ACCESS_KEY_ID;
  const secret = envVars.AWS_SECRET_ACCESS_KEY;

  if (!keyId || !secret) return { status: 'MISSING', message: 'AWS credentials not set' };

  if (isCanaryValue(keyId) || isCanaryValue(secret)) {
