async function main() {
  const tests = [
    { name: 'Database', check: checkDatabase },
    { name: 'AWS', check: checkAWS },
    { name: 'Anthropic', check: checkAnthropic },
    { name: 'Stripe', check: checkStripe },
    { name: 'Logfire', check: checkLogfire }
  ];

  const results = {};
  let validCount = 0, invalidCount = 0, canaryCount = 0, skipCount = 0;

  for (const { name, check } of tests) {
    try {
      const result = await check();
      results[name] = result;

      const statusChar = result.status === 'VALID' ? '✓' :
                        result.status === 'INVALID' ? '❌' :
                        result.status === 'CANARY' ? '⚠️' : 'ℹ️';

      console.log(`${statusChar} ${name}: ${result.status}`);
      console.log(`  ${result.message}`);
      if (result.details) console.log(`  ${result.details}`);
      console.log();

      if (result.status === 'VALID') validCount++;
      else if (result.status === 'INVALID') invalidCount++;
      else if (result.status === 'CANARY') canaryCount++;
      else skipCount++;
    } catch (error) {
      results[name] = { status: 'ERROR', message: error.message };
      console.log(`❌ ${name}: ERROR - ${error.message}\n`);
      invalidCount++;
    }
  }

  // Summary
  console.log('──────────────────────────────────────');
  console.log('=== Summary ===');
  console.log(`Valid: ${validCount} | Invalid: ${invalidCount} | Canary/Test: ${canaryCount} | Skipped: ${skipCount}`);

  if (invalidCount > 0) {
    console.log('\n⚠️  Some credentials are invalid or expired.');
    console.log('   Update .env.test with valid values and re-run this script.');
    process.exit(1);
  } else if (canaryCount === Object.keys(results).length) {
    console.log('\nℹ️  All credentials are canary/test values.');
    console.log('   To verify real credentials, replace them in .env.test and re-run.');
  } else if (validCount > 0 || (validCount === 0 && canaryCount === 0)) {
    console.log('\n✓ All provided credentials appear to be valid.');
  }
}

main().catch(console.error);

