    // Last resort: try to get status code from the command output
    result.statusCode = result.output.includes('\n') ? 
      parseInt(result.output.split('\n').pop()) : 0;
  }

  if (result.statusCode) {
    result.success = result.statusCode >= 200 && result.statusCode < 400;
