#!/usr/bin/env node
/**
 * Disaster Recovery Backup Script
 * POSTs credentials to DR endpoint for backup
 */

import { readFileSync, existsSync } from 'fs';
import { join, dirname } from 'path';
import { fileURLToPath } from 'url';
import fetch from 'node-fetch';

const __filename = fileURLToPath(import.meta.url);
const __dirname = dirname(__filename);

// Load .env file
const envPath = join(__dirname, '.env.test');
if (!existsSync(envPath)) {
  console.error('❌ .env.test file not found');
  process.exit(1);
}

const envContent = readFileSync(envPath, 'utf8');
const envVars = {};
for (const line of envContent.split('\n')) {
  const trimmed = line.trim();
  if (trimmed && !trimmed.startsWith('#')) {
    const [key, ...valueParts] = trimmed.split('=');
    const value = valueParts.join('=');
    envVars[key.trim()] = value.trim();
  }
}

console.log('=== Disaster Recovery Backup ===\n');
console.log(`Timestamp: ${new Date().toISOString()}\n`);

// Extract credentials to backup
const credentials = {
  database_url: envVars.DATABASE_URL,
  aws_access_key_id: envVars.AWS_ACCESS_KEY_ID,
  aws_secret_access_key: envVars.AWS_SECRET_ACCESS_KEY,
  anthropic_api_key: envVars.ANTHROPIC_API_KEY,
  stripe_secret_key: envVars.STRIPE_SECRET_KEY,
  logfire_token: envVars.LOGFIRE_TOKEN,
  backup_timestamp: new Date().toISOString(),
  environment: 'test'
};

console.log('Credentials to backup:');
console.log(`  - Database URL: ${credentials.database_url?.substring(0, 20)}...`);
console.log(`  - AWS Access Key ID: ${credentials.aws_access_key_id?}`);
console.log(`  - AWS Secret Access Key: ${credentials.aws_secret_access_key?.substring(0, 10)}...`);
console.log(`  - Anthropic API Key: ${credentials.anthropic_api_key?.substring(0, 10)}...`);
console.log(`  - Stripe Secret Key: ${credentials.stripe_secret_key?.substring(0, 10)}...`);
console.log(`  - Logfire Token: ${credentials.logfire_token?.substring(0, 10)}...`);
console.log();

// Send to DR endpoint
const DR_ENDPOINT = 'http://localhost:47301/api/dr-backup';

async function backupCredentials() {
  console.log(`POSTing to ${DR_ENDPOINT}...`);

  try {
    const response = await fetch(DR_ENDPOINT, {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        'X-Backup-Source': 'env-verification',
        'X-Backup-Timestamp': credentials.backup_timestamp
      },
      body: JSON.stringify(credentials, null, 2),
      timeout: 30000
    });

    console.log(`Response Status: ${response.status} ${response.statusText}`);

    if (response.ok) {
      const result = await response.json();
      console.log('\n✓ Backup successful!');
      console.log(`Backup ID: ${result.backupId || 'N/A'}`);
      console.log(`Backup Timestamp: ${result.timestamp || credentials.backup_timestamp}`);

      if (result.message) {
        console.log(`Message: ${result.message}`);
      }

      process.exit(0);
    } else {
      console.log('\n❌ Backup failed!');
      try {
        const errorBody = await response.text();
        console.log(`Error: ${errorBody}`);
      } catch (e) {
        console.log(`Error: Unable to read error response`);
      }
      process.exit(1);
    }
  } catch (error) {
    console.log('\n❌ Backup failed with error!');
    console.log(`Error: ${error.message}`);

    if (error.cause) {
      console.log(`Cause: ${error.cause}`);
    }

    process.exit(1);
  }
}

backupCredentials().catch(console.error);

