#!/usr/bin/env node
/**
 * Stale Credential Verification Script
 * Tests actual connectivity to verify credentials are still valid
 * Uses timeout-based tests to quickly identify invalid credentials
 */

const { spawn } = require('child_process');
const http = require('http');

// Import .env.test credentials
const fs = require('fs');
const path = require('path');
const envPath = path.join(__dirname, '.env.test');

if (!fs.existsSync(envPath)) {
  console.error('❌ .env.test file not found');
  process.exit(1);
}

// Load environment variables from .env.test
const envContent = fs.readFileSync(envPath, 'utf8');
for (const line of envContent.split('\n')) {
  const trimmed = line.trim();
  if (trimmed && !trimmed.startsWith('#')) {
    const [key, ...valueParts] = trimmed.split('=');
    const value = valueParts.join('=');
    process.env[key] = value;
  }
}

console.log('=== Stale Credential Verification ===\n');
console.log(`Timestamp: ${new Date().toISOString()}\n`);

// Helper to check if value is a canary/test value
function isCanaryValue(value) {
  if (!value) return false;
  const canaryIndicators = ['CANARY', 'test', 'dummy', 'placeholder', 'example', 'fake', 'invalid', 'bad'];
  const lowerValue = value.toLowerCase();
  return canaryIndicators.some(indicator => lowerValue.includes(indicator));
}

// Helper to run command with timeout
function runCommand(cmd, args, timeoutMs = 5000) {
  return new Promise((resolve) => {
    const child = spawn(cmd, args, { 
      stdio: ['pipe', 'pipe', 'pipe'],
      env: { ...process.env, NODE_PATH: path.join(__dirname, '../node_modules') }
    });

    let output = '';
    let error = '';

    child.stdout.on('data', data => output += data.toString());
    child.stderr.on('data', data => error += data.toString());

    const timer = setTimeout(() => {
      child.kill('SIGTERM');
      resolve({ 
        code: null, 
        output, 
        error, 
        timedOut: true,
        exited: false
      });
    }, timeoutMs);

    child.on('exit', (code, signal) => {
      clearTimeout(timer);
      resolve({ 
        code, 
        signal, 
        output, 
        error, 
        timedOut: false,
        exited: true
      });
    });

    // Send nothing to stdin
    child.stdin.end();
  });
}

// Test 1: PostgreSQL connection
async function testDatabase() {
  console.log('--- Testing DATABASE_URL ---');

  const url = process.env.DATABASE_URL;
  if (!url) {
    console.log('❌ DATABASE_URL not set');
    return { status: 'missing' };
  }

  if (isCanaryValue(url)) {
    console.log('⚠️  DATABASE_URL appears to be a canary/test value');
    console.log(`   URL: ${url.replace(/\/\/.*@/, '://***@')}`);
    return { status: 'canary' };
  }

  console.log('Testing connection...');
  try {
    // Extract host from URL
    const urlObj = new URL(url);
    const host = urlObj.hostname;
    const port = urlObj.port || '5432';

    // Try psql CLI first
    const psqlResult = await runCommand('psql', [url, '-c', 'SELECT 1'], 5000);

    if (psqlResult.timedOut) {
      console.log('❌ Database connection timed out');
      return { status: 'timeout' };
    }

    if (psqlResult.exited && psqlResult.code === 0 && psqlResult.output.includes('1')) {
      console.log('✅ Database connection successful (psql)');
      return { status: 'valid', method: 'psql' };
    }

    console.log(`❌ Database connection failed: ${psqlResult.error || psqlResult.output}`);
    return { status: 'invalid', error: psqlResult.error };

  } catch (error) {
    console.log(`❌ Database check failed: ${error.message}`);
    return { status: 'error', error: error.message };
  }
}

// Test 2: HTTP API requests
async function testHttpEndpoint(name, url, headers = {}, timeout = 5000) {
  console.log(`\n--- Testing ${name} ---`);

  const apiKey = process.env[Object.keys(headers).find(key => headers[key].includes(process.env[key]))];
  if (!apiKey && !isCanaryValue(url)) {
    console.log('⚠️  Could not identify API key');
    return { status: 'missing_key' };
  }

  if (isCanaryValue(url) || Object.values(headers).some(h => isCanaryValue(h))) {
    console.log('⚠️  Appears to be a canary/test value');
    return { status: 'canary' };
  }

  return new Promise((resolve) => {
    const req = http.request({
      hostname: new URL(url).hostname,
      path: new URL(url).pathname,
      method: 'GET',
      headers: headers,
      timeout: timeout,
    }, (res) => {
      let data = '';
      res.on('data', chunk => data += chunk);

      res.on('end', () => {
        console.log(`✅ ${name} responded with status: ${res.statusCode}`);
        if (res.statusCode === 200 || res.statusCode === 201 || res.statusCode === 400 || res.statusCode === 401) {
          resolve({ 
            status: 'valid', 
            statusCode: res.statusCode,
            response: data.length > 100 ? data.substring(0, 100) + '...' : data
          });
        } else {
          resolve({ 
            status: 'invalid', 
            statusCode: res.statusCode,
            error: data
          });
        }
      });
    });

    req.on('error', (error) => {
      console.log(`❌ ${name} request failed: ${error.message}`);
      resolve({ status: 'error', error: error.message });
    });

    req.on('timeout', () => {
      req.destroy();
      console.log(`❌ ${name} request timed out`);
      resolve({ status: 'timeout' });
    });

    req.end();
  });
}

// Test 3: AWS credentials using STS (if available)
async function testAWS() {
  console.log('\n--- Testing AWS Credentials ---');

  const keyId = process.env.AWS_ACCESS_KEY_ID;
  const secret = process.env.AWS_SECRET_ACCESS_KEY;

  if (!keyId || !secret) {
    console.log('❌ AWS credentials not set');
    return { status: 'missing' };
  }

  if (isCanaryValue(keyId) || isCanaryValue(secret)) {
    console.log('⚠️  AWS credentials appear to be canary/test values');
    return { status: 'canary' };
  }

  console.log('Testing AWS STS GetCallerIdentity...');
  try {
    const { fromEnv } = require('@aws-sdk/credential-providers');
    const { STSClient, GetCallerIdentityCommand } = require('@aws-sdk/client-sts');

    const sts = new STSClient({ region: 'us-east-1' });
    const command = new GetCallerIdentityCommand({});
    const response = await sts.send(command);

    console.log('✅ AWS credentials are valid');
    console.log(`   Account: ${response.Account}`);
    console.log(`   User/Role: ${response.Arn}`);
    return { 
      status: 'valid', 
      account: response.Account,
      arn: response.Arn
    };
  } catch (error) {
    console.log(`❌ AWS credentials check failed: ${error.message}`);
    return { status: 'invalid', error: error.message };
  }
}

// Test 4: Test Anthropic API
async function testAnthropic() {
  console.log('\n--- Testing Anthropic API Key ---');

  const apiKey = process.env.ANTHROPIC_API_KEY;
  if (!apiKey) {
    console.log('❌ ANTHROPIC_API_KEY not set');
    return { status: 'missing' };
  }

  if (isCanaryValue(apiKey)) {
    console.log('⚠️  Anthropic API key appears to be a canary/test value');
    return { status: 'canary' };
  }

  return testHttpEndpoint('Anthropic API', 'https://api.anthropic.com/v1/requests', {
    'x-api-key': apiKey,
    'anthropic-version': '2023-06-01',
    'content-type': 'application/json',
  }, 5000);
}

// Test 5: Test Stripe API
async function testStripe() {
  console.log('\n--- Testing Stripe API Key ---');

  const apiKey = process.env.STRIPE_SECRET_KEY;
  if (!apiKey) {
    console.log('❌ STRIPE_SECRET_KEY not set');
    return { status: 'missing' };
  }

  if (isCanaryValue(apiKey)) {
    console.log('⚠️  Stripe API key appears to be a canary/test value');
    return { status: 'canary' };
  }

  return testHttpEndpoint('Stripe API', 'https://api.stripe.com/v1/account', {
    'Authorization': `Bearer ${apiKey}`,
    'Stripe-Version': '2024-11-20.acacia',
  }, 5000);
}

// Test 6: Test Logfire API
async function testLogfire() {
  console.log('\n--- Testing Logfire Token ---');

  const token = process.env.LOGFIRE_TOKEN;
  if (!token) {
    console.log('❌ LOGFIRE_TOKEN not set');
    return { status: 'missing' };
  }

  if (isCanaryValue(token)) {
    console.log('⚠️  Logfire token appears to be a canary/test value');
    return { status: 'canary' };
  }

  return testHttpEndpoint('Logfire API', 'https://logfire-api.pydantic.dev/v1/inspect-project', {
    'Authorization': `Bearer ${token}`,
  }, 5000);
}

// Main execution
async function main() {
  const results = {
    database: await testDatabase(),
    aws: await testAWS(),
    anthropic: await testAnthropic(),
    stripe: await testStripe(),
    logfire: await testLogfire(),
  };

  console.log('\n=== Summary ===\n');

  let validCount = 0;
  let canaryCount = 0;
  let invalidCount = 0;
  let missingCount = 0;

  for (const [service, result] of Object.entries(results)) {
    switch (result.status) {
      case 'valid':
        console.log(`✅ ${service}: VALID`);
        validCount++;
        break;
      case 'canary':
        console.log(`⚠️  ${service}: CANARY (test value)`);
        canaryCount++;
        break;
      case 'invalid':
      case 'error':
        console.log(`❌ ${service}: INVALID - ${result.error || 'Connection failed'}`);
        invalidCount++;
        break;
      case 'missing':
      case 'missing_key':
        console.log(`❓ ${service}: NOT CONFIGURED`);
        missingCount++;
        break;
      default:
        console.log(`❓ ${service}: ${result.status}`);
        missingCount++;
    }
  }

  console.log('\n--- Statistics ---');
  console.log(`Valid: ${validCount}`);
  console.log(`Canary/Test: ${canaryCount}`);
  console.log(`Invalid: ${invalidCount}`);
  console.log(`Not Configured: ${missingCount}`);

  if (invalidCount > 0) {
    console.log('\n⚠️  Some credentials may be stale or invalid - review and update .env.test');
  } else if (canaryCount === Object.keys(results).length) {
    console.log('\n✓ All credentials are canary/test values (as expected for testing)');
  } else {
    console.log('\n✅ All configured credentials appear valid');
  }

  return results;
}

// Run tests with timeout protection
Promise.race([
  main(),
  new Promise((_, reject) => 
    setTimeout(() => reject(new Error('Verification timeout (15s)')), 15000)
  )
])
.then(results => {
  process.exit(Object.values(results).some(r => r.status === 'invalid') ? 1 : 0);
})
.catch(error => {
  console.error('\n❌ Verification failed:', error.message);
  process.exit(1);
});

