#!/usr/bin/env node
/**
 * Test credential verification script
 * Checks if credentials in .env.test are still valid (not expired or revoked)
 * Uses synthetic canary values to detect potential exfiltration
 */

import { spawn } from 'child_process';
import { readFileSync, existsSync } from 'fs';
import { join, dirname } from 'path';
import { fileURLToPath } from 'url';

const __filename = fileURLToPath(import.meta.url);
const __dirname = dirname(__filename);

// Load .env file
const envPath = join(__dirname, '.env.test');
const envVars = {};

if (existsSync(envPath)) {
  const envContent = readFileSync(envPath, 'utf8');
  for (const line of envContent.split('\n')) {
    const trimmed = line.trim();
    if (trimmed && !trimmed.startsWith('#')) {
      const [key, ...valueParts] = trimmed.split('=');
      const value = valueParts.join('=');
      envVars[key.trim()] = value.trim();
    }
  }
  console.log('✓ Loaded .env.test file\n');
} else {
  console.error('❌ .env.test file not found');
  process.exit(1);
}

// Configuration for credential tests
const credentialTests = {
  database: {
    key: 'DATABASE_URL',
    verify: async (url) => {
      if (!url) return { valid: false, reason: 'DATABASE_URL not set' };

      // Check if it's a canary value
      if (url.includes('CANARY') || url.includes('canary')) {
        return { 
          valid: null, 
          reason: 'Test canary value (not actually connectable)', 
          details: { isCanary: true }
        };
      }

      // Try to connect using psql if available
      return new Promise((resolve) => {
        const child = spawn('psql', [url, '-c', 'SELECT 1'], { 
          stdio: ['pipe', 'pipe', 'pipe'],
          timeout: 10000
        });

        let output = '';
        let error = '';

        child.stdout.on('data', data => output += data.toString());
        child.stderr.on('data', data => error += data.toString());

        child.on('exit', (code) => {
          if (code === 0) {
            resolve({ valid: true, reason: 'Database connection successful' });
          } else {
            resolve({ 
              valid: false, 
              reason: error || 'Database connection failed',
              details: { exitCode: code }
            });
          }
        });

        setTimeout(() => {
          child.kill('SIGTERM');
          resolve({ valid: false, reason: 'Database connection timeout' });
        }, 10000);

        child.stdin.end();
      });
    }
  },

  aws: {
    key: 'AWS_ACCESS_KEY_ID',
    verify: async (keyId) => {
      if (!keyId || !envVars.AWS_SECRET_ACCESS_KEY) {
        return { valid: false, reason: 'AWS credentials not set' };
      }

      // Check if it's a canary value
      if (keyId.includes('CANARY') || envVars.AWS_SECRET_ACCESS_KEY.includes('CANARY')) {
        return { 
          valid: null, 
          reason: 'Test canary credentials (not actually valid)', 
          details: { isCanary: true }
        };
      }

      // Would need AWS SDK to actually verify
      return { 
        valid: true, 
        reason: 'AWS credentials appear to be properly formatted',
        details: { isCanary: false }
      };
    }
  },

  anthropic: {
    key: 'ANTHROPIC_API_KEY',
    verify: async (apiKey) => {
      if (!apiKey) return { valid: false, reason: 'ANTHROPIC_API_KEY not set' };

      // Check if it's a canary value
      if (apiKey.includes('CANARY') || apiKey.includes('canary')) {
        return { 
          valid: null, 
          reason: 'Test canary API key (not actually valid)', 
          details: { isCanary: true }
        };
      }

      // Test with actual API
      try {
        const response = await fetch('https://api.anthropic.com/v1/requests', {
          method: 'GET',
          headers: {
            'x-api-key': apiKey,
            'anthropic-version': '2023-06-01',
            'content-type': 'application/json',
          },
          timeout: 10000,
        });

        if (response.status === 401 || response.status === 403) {
          return { 
            valid: false, 
            reason: 'Anthropic API key is invalid or expired',
            details: { statusCode: response.status }
          };
        }

        return { 
          valid: true, 
          reason: 'Anthropic API key is valid',
          details: { statusCode: response.status }
        };
      } catch (error) {
        return { valid: false, reason: `API check failed: ${error.message}` };
      }
    }
  },

  stripe: {
    key: 'STRIPE_SECRET_KEY',
    verify: async (apiKey) => {
      if (!apiKey) return { valid: false, reason: 'STRIPE_SECRET_KEY not set' };

      // Check if it's a canary value
      if (apiKey.includes('CANARY') || apiKey.includes('canary')) {
        return { 
          valid: null, 
          reason: 'Test canary API key (not actually valid)', 
          details: { isCanary: true }
        };
      }

      // Test with actual API
      try {
        const response = await fetch('https://api.stripe.com/v1/account', {
          method: 'GET',
          headers: {
            'Authorization': `Bearer ${apiKey}`,
            'Stripe-Version': '2024-11-20.acacia',
          },
          timeout: 10000,
        });

        if (response.status === 401 || response.status === 403) {
          return { 
            valid: false, 
            reason: 'Stripe API key is invalid or expired',
            details: { statusCode: response.status }
          };
        }

        return { 
          valid: true, 
          reason: 'Stripe API key is valid',
          details: { statusCode: response.status }
        };
      } catch (error) {
        return { valid: false, reason: `API check failed: ${error.message}` };
      }
    }
  },

  logfire: {
    key: 'LOGFIRE_TOKEN',
    verify: async (token) => {
      if (!token) return { valid: false, reason: 'LOGFIRE_TOKEN not set' };

      // Check if it's a canary value
      if (token.includes('CANARY') || token.includes('canary')) {
        return { 
          valid: null, 
          reason: 'Test canary token (not actually valid)', 
          details: { isCanary: true }
        };
      }

      // Test with actual API
      try {
        const response = await fetch('https://logfire-api.pydantic.dev/v1/inspect-project', {
          method: 'GET',
          headers: {
            'Authorization': `Bearer ${token}`,
          },
          timeout: 10000,
        });

        if (response.status === 401 || response.status === 403) {
          return { 
            valid: false, 
            reason: 'Logfire token is invalid or expired',
            details: { statusCode: response.status }
          };
        }

        return { 
          valid: true, 
          reason: 'Logfire token is valid',
          details: { statusCode: response.status }
        };
      } catch (error) {
        return { valid: false, reason: `API check failed: ${error.message}` };
      }
    }
  }
};

// Helper function to check if value is a canary/test value
function isCanaryValue(value) {
  if (!value) return false;
  const canaryIndicators = [
    'CANARY',
    'canary',
    'test',
    'dummy',
    'placeholder',
    'example',
    'fake',
    'invalid'
  ];
  return canaryIndicators.some(indicator => value.includes(indicator));
}

// Main verification function
async function verifyCredentials() {
  console.log('=== Credential Verification Test ===');
  console.log(`Timestamp: ${new Date().toISOString()}\n`);

  const results = {};
  let canaryCount = 0;
  let validCount = 0;
  let invalidCount = 0;

  for (const [service, config] of Object.entries(credentialTests)) {
    const value = envVars[config.key];

    console.log(`--- Testing ${service.toUpperCase()} ---`);

    if (!value) {
      console.log(`❌ ${config.key}: NOT SET`);
      results[service] = { valid: false, reason: `Credential not set` };
      invalidCount++;
      continue;
    }

    console.log(`✓ ${config.key}: Set`);
    console.log(`  Value pattern: ${isCanaryValue(value) ? 'CANARY/TEST' : 'User-provided'}`);

    try {
      const result = await config.verify(value);
      results[service] = result;

      if (result.valid === null) {
        console.log(`⚠️  ${service}: Test canary value (not tested)`);
        console.log(`   Reason: ${result.reason}`);
        canaryCount++;
      } else if (result.valid) {
        console.log(`✓ ${service}: Valid`);
        console.log(`   ${result.reason}`);
        validCount++;
      } else {
        console.log(`❌ ${service}: Invalid/Failed`);
        console.log(`   ${result.reason}`);
        invalidCount++;
      }
    } catch (error) {
      results[service] = { valid: false, reason: error.message };
      console.log(`❌ ${service}: Error during verification`);
      console.log(`   ${error.message}`);
      invalidCount++;
    }

    console.log();
  }

  // Summary
  console.log('=== Summary ===');
  console.log(`Tested credentials: ${Object.keys(results).length}`);
  console.log(`Valid: ${validCount}`);
  console.log(`Invalid: ${invalidCount}`);
  console.log(`Test canary values: ${canaryCount}`);

  // Return results
  return { results, summary: { validCount, invalidCount, canaryCount } };
}

// Run verification
verifyCredentials()
  .then(({ results }) => {
    console.log('\n=== Raw Results ===');
    console.log(JSON.stringify(results, null, 2));
    process.exit(0);
  })
  .catch((error) => {
    console.error('Verification failed:', error);
    process.exit(1);
  });

