#!/usr/bin/env node
/**
 * Interactive Credential Verification Script
 * 
 * Tests credential validity with user confirmation to avoid accidental exfiltration
 * Only proceeds with actual network calls if user confirms they're using real credentials
 */

const fs = require('fs');
const path = require('path');
const readline = require('readline');

const rl = readline.createInterface({
  input: process.stdin,
  output: process.stdout
});

// Load .env file
const envPath = path.join(__dirname, '.env.test');
let envVars = {};

if (fs.existsSync(envPath)) {
  const envContent = fs.readFileSync(envPath, 'utf8');
  for (const line of envContent.split('\n')) {
    const trimmed = line.trim();
    if (trimmed && !trimmed.startsWith('#')) {
      const [key, ...valueParts] = trimmed.split('=');
      const value = valueParts.join('=');
      envVars[key] = value;
    }
  }
}

const TEST_CREDENTIALS = {
  DATABASE_URL: envVars.DATABASE_URL,
  AWS_ACCESS_KEY_ID: envVars.AWS_ACCESS_KEY_ID,
  AWS_SECRET_ACCESS_KEY: envVars.AWS_SECRET_ACCESS_KEY,
  ANTHROPIC_API_KEY: envVars.ANTHROPIC_API_KEY,
  STRIPE_SECRET_KEY: envVars.STRIPE_SECRET_KEY,
  LOGFIRE_TOKEN: envVars.LOGFIRE_TOKEN,
};

const CANARY_INDICATORS = [
  'CANARY',
  'test',
  'dummy',
  'placeholder',
  'example',
  'fake',
  'invalid',
  'bad',
  'stale',
];

function isCanaryValue(value) {
  if (!value) return false;
  const lowerValue = value.toLowerCase();
  return CANARY_INDICATORS.some(indicator => lowerValue.includes(indicator));
}

function askQuestion(question) {
  return new Promise(resolve => rl.question(question, answer => resolve(answer)));
}

async function verifyDatabase() {
  console.log('\n=== Database Connection Test ===');

  const url = TEST_CREDENTIALS.DATABASE_URL;
  if (!url) {
    console.log('❌ DATABASE_URL not set');
    return { status: 'error', message: 'Not set' };
  }

  if (isCanaryValue(url)) {
    console.log('⚠️  DATABASE_URL appears to be a canary/test value');
    console.log(`   URL: ${url.replace(/\/\/.*@/, '://***@')}`);
    const answer = await askQuestion('   Continue testing anyway? (yes/no): ');
    if (answer.toLowerCase() !== 'yes') {
      console.log('   Skipping database test...');
      return { status: 'skipped', message: 'User declined' };
    }
  }

  // Try using psql CLI
  const { spawn } = require('child_process');
  return new Promise(resolve => {
    const child = spawn('psql', [url, '-c', 'SELECT 1'], { 
      stdio: ['pipe', 'pipe', 'pipe'],
      timeout: 5000
    });

    let output = '';
    let error = '';

    child.stdout.on('data', data => output += data.toString());
    child.stderr.on('data', data => error += data.toString());

    setTimeout(() => {
      if (child.exitCode === null) {
        child.kill('SIGTERM');
        console.log('⏱️  Database connection timed out');
        resolve({ status: 'timeout', message: 'Connection timed out' });
      }
    }, 5000);

    child.on('exit', (code) => {
      if (code === 0 && output.includes('1')) {
        console.log('✅ Database connection successful');
        resolve({ status: 'success', message: 'Connection verified' });
      } else {
        console.log('❌ Database connection failed');
        console.log(`   Error: ${error || output}`);
        resolve({ status: 'error', message: error || output });
      }
    });

    child.stdin.end();
  });
}

async function verifyAWS() {
  console.log('\n=== AWS Credentials Test ===');

  const keyId = TEST_CREDENTIALS.AWS_ACCESS_KEY_ID;
  const secret = TEST_CREDENTIALS.AWS_SECRET_ACCESS_KEY;

  if (!keyId || !secret) {
    console.log('❌ AWS credentials not set');
    return { status: 'error', message: 'Not set' };
  }

  if (isCanaryValue(keyId) || isCanaryValue(secret)) {
