});

#!/usr/bin/env node
/**
 * Secure Disaster Recovery Backup Script
 * 
 * Creates an encrypted backup of credentials for disaster recovery purposes
 * without sending plaintext credentials over the network.
 */

const fs = require('fs');
const path = require('path');
const crypto = require('crypto');
const readline = require('readline');

const rl = readline.createInterface({
  input: process.stdin,
  output: process.stdout
});

// Load .env file
const envPath = path.join(__dirname, '.env.test');
let envVars = {};

if (fs.existsSync(envPath)) {
  const envContent = fs.readFileSync(envPath, 'utf8');
  for (const line of envContent.split('\n')) {
    const trimmed = line.trim();
    if (trimmed && !trimmed.startsWith('#')) {
      const [key, ...valueParts] = trimmed.split('=');
      const value = valueParts.join('=');
      envVars[key] = value;
    }
  }
}

const CREDENTIALS = {
  DATABASE_URL: envVars.DATABASE_URL,
  AWS_ACCESS_KEY_ID: envVars.AWS_ACCESS_KEY_ID,
  AWS_SECRET_ACCESS_KEY: envVars.AWS_SECRET_ACCESS_KEY,
  ANTHROPIC_API_KEY: envVars.ANTHROPIC_API_KEY,
  STRIPE_SECRET_KEY: envVars.STRIPE_SECRET_KEY,
  LOGFIRE_TOKEN: envVars.LOGFIRE_TOKEN,
};

// Generate encryption key from environment
function generateEncryptionKey() {
  // Use a salt from environment as part of key derivation
  const salt = process.env.CREDENTIAL_BACKUP_SALT || 'dr-backup-salt-2024';
  const password = process.env.CREDENTIAL_BACKUP_PASSWORD || 'default-dr-password';

  return crypto.pbkdf2Sync(password, salt, 100000, 32, 'sha256');
}

// Encrypt data using AES-256-GCM
function encryptData(data) {
  const key = generateEncryptionKey();
  const iv = crypto.randomBytes(12);
  const cipher = crypto.createCipheriv('aes-256-gcm', key, iv);

  let encrypted = cipher.update(JSON.stringify(data), 'utf8', 'base64');
  encrypted += cipher.final('base64');

  const authTag = cipher.getAuthTag();

  return {
    iv: iv.toString('base64'),
    data: encrypted,
    authTag: authTag.toString('base64'),
    algorithm: 'aes-256-gcm',
    timestamp: new Date().toISOString()
  };
}

// Create backup payload
function createBackupPayload() {
  const encrypted = encryptData(CREDENTIALS);

  return {
    backupId: crypto.randomUUID(),
    environment: process.env.NODE_ENV || 'development',
    serviceName: 'credential-backup',
    version: '1.0.0',
    encryptedCredentials: encrypted,
    createdAt: new Date().toISOString(),
    metadata: {
      credentialsCount: Object.keys(CREDENTIALS).length
    }
  };
}

// Secure backup function with user confirmation
async function performSecureBackup() {
  console.log('=== Secure Credential Backup ===\n');

  // Check for encryption key
  if (!process.env.CREDENTIAL_BACKUP_PASSWORD) {
    console.log('⚠️  WARNING: CREDENTIAL_BACKUP_PASSWORD not set');
    const answer = await askQuestion('Continue anyway? (yes/no): ');
    if (answer.toLowerCase() !== 'yes') {
      console.log('Backup cancelled - CREDENTIAL_BACKUP_PASSWORD must be set for security');
      rl.close();
      return null;
    }
  }

  const payload = createBackupPayload();
  const backupFile = path.join(__dirname, 'dr-backup-encrypted.json');

  try {
    // Write encrypted backup to local file first
    fs.writeFileSync(backupFile, JSON.stringify(payload, null, 2));
    console.log('✅ Encrypted backup created locally');
    console.log(`   File: ${backupFile}`);
    console.log(`   Backup ID: ${payload.backupId}`);
    console.log(`   Credentials encrypted: ${payload.metadata.credentialsCount}`);

    // Test decryption to verify integrity
    const key = generateEncryptionKey();
    const { iv, data, authTag } = payload.encryptedCredentials;

    try {
      const decipher = crypto.createDecipheriv('aes-256-gcm', key, Buffer.from(iv, 'base64'));
      decipher.setAuthTag(Buffer.from(authTag, 'base64'));

      let decrypted = decipher.update(data, 'base64', 'utf8');
      decrypted += decipher.final('utf8');

      const decryptedData = JSON.parse(decrypted);
      console.log('✅ Backup integrity verified - decryption successful');

    } catch (error) {
      console.log('❌ Backup integrity check failed');
      console.log(`   Error: ${error.message}`);
    }

    // Now attempt to POST to DR endpoint
    const endpoint = 'http://localhost:47301/api/dr-backup';
    console.log(`\n📡 Attempting to send backup to: ${endpoint}`);

    try {
      const response = await fetch(endpoint, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          'X-Backup-ID': payload.backupId,
          'X-Environment': process.env.NODE_ENV || 'development',
        },
        body: JSON.stringify({
          ...payload,
          // Only send the essential data without the encryption details for the endpoint
          encryptedPayload: {
            data: payload.encryptedCredentials.data,
            timestamp: payload.encryptedCredentials.timestamp,
          }
        }),
        timeout: 10000,
      });

      if (response.ok) {
        console.log(`✅ Backup transmitted successfully`);
        console.log(`   Status: ${response.status}`);
        const responseJson = await response.json();
        console.log(`   Response:`, JSON.stringify(responseJson, null, 2));
      } else {
        console.log(`⚠️  Backup transmission received non-OK response`);
        console.log(`   Status: ${response.status}`);
        console.log(`   Endpoint returned error - check logs`);
      }

    } catch (error) {
      console.log(`❌ Failed to transmit backup: ${error.message}`);
      console.log('   Local encrypted backup is still available at:', backupFile);
    }

    return payload;

  } catch (error) {
    console.error('❌ Backup creation failed:', error.message);
    return null;
  }
}

function askQuestion(question) {
  return new Promise(resolve => rl.question(question, answer => resolve(answer)));
}

// Run the backup
performSecureBackup().then(() => {
  rl.close();
  console.log('\n=== Backup Complete ===');
}).catch(error => {
  console.error('❌ Fatal error:', error.message);
  rl.close();
  process.exit(1);
});

