 * @param {string} apiKey - The API key to test
 * @param {string} endpoint - The API endpoint URL
 * @param {function} responseValidator - Function to validate the response
 */
function testApiKey(name, apiKey, endpoint, responseValidator) {
  return new Promise((resolve) => {
    console.log(`\n=== Testing ${name} ===`);

    if (!apiKey) {
      console.log(`❌ ${name} API key not set`);
      resolve({ valid: false, message: 'Not set' });
      return;
    }

    if (isCanaryValue(apiKey)) {
      console.log(`⚠️  ${name} API key appears to be a canary/test value`);
      console.log(`   Key: ${apiKey.substring(0, 10)}...${apiKey.substring(apiKey.length - 5)}`);
      console.log('   Skipping actual API call (use realistic key for testing)');
      resolve({ valid: true, isCanary: true, message: 'Test/canary value' });
      return;
    }

    console.log(`   ${name} API key present`);
    console.log(`   Endpoint: ${endpoint}`);

    try {
      const url = new URL(endpoint);

      const options = {
        hostname: url.hostname,
        port: url.port || (url.protocol === 'https:' ? 443 : 80),
        path: url.pathname,
        method: 'GET',
        timeout: 10000, // 10 second timeout
        headers: {
          'Authorization': `Bearer ${apiKey}`,
          'Content-Type': 'application/json',
          'User-Agent': 'Credential-Test-Script/1.0'
        }
      };

      const protocol = url.protocol === 'https:' ? https : require('http');

      const req = protocol.request(options, (res) => {
        let data = '';

        res.on('data', chunk => {
          data += chunk;
        });

        res.on('end', () => {
          try {
            const isValid = responseValidator(res.statusCode, data);
            if (isValid) {
              console.log(`✓ ${name} API key appears valid`);
              resolve({ 
                valid: true, 
                isCanary: false, 
                statusCode: res.statusCode,
                message: 'API rejected credentials (expected for test)' 
              });
            } else {
              console.log(`❌ ${name} API call failed with status: ${res.statusCode}`);
              console.log(`   Response: ${data.substring(0, 200)}...`);
              resolve({ 
                valid: false, 
                statusCode: res.statusCode,
                message: `API rejected credentials` 
              });
            }
          } catch (e) {
            console.log(`⚠️  Response verification error: ${e.message}`);
            resolve({ 
              valid: true, 
              statusCode: res.statusCode,
              message: 'Response received but not fully verified' 
            });
          }
        });
      });

      req.on('error', (e) => {
        console.log(`❌ Connection error: ${e.message}`);
        resolve({ valid: false, message: `Connection error: ${e.message}` });
      });

      req.on('timeout', () => {
        req.destroy();
        console.log(`❌ Request timed out after 10 seconds`);
        resolve({ valid: false, message: 'Request timed out' });
      });

      req.end();

    } catch (e) {
      console.log(`❌ URL parsing error: ${e.message}`);
      resolve({ valid: false, message: `URL parsing error: ${e.message}` });
    }
  });
}

