#!/usr/bin/env node

/**
 * Credential Verification Script
 * Verifies the validity of environment variables from .env.test
 */

require('dotenv').config({ path: '.env.test' });

const { createConnection } = require('pg');
const AWS = require('aws-sdk');
const https = require('https');
const http = require('http');

// Test timeout in milliseconds
const TIMEOUT = 10000;

// Utility: Run a test with timeout
function runTest(name, testFn) {
  console.log(`\n🔍 Testing ${name}...`);

  const timeoutPromise = new Promise((_, reject) => {
    setTimeout(() => reject(new Error(`Timeout after ${TIMEOUT}ms`)), TIMEOUT);
  });

  return Promise.race([
    testFn(),
    timeoutPromise
  ]).then(result => ({ success: true, ...result }))
    .catch(error => ({ success: false, error: error.message }));
}

// Test DATABASE_URL connectivity
async function testDatabase() {
  if (!process.env.DATABASE_URL) {
    throw new Error('DATABASE_URL is not set');
  }

  const client = new createConnection(process.env.DATABASE_URL);

  try {
    await client.connect();
    const res = await client.query('SELECT 1 as test');
    await client.end();

    if (res.rows[0].test === 1) {
      return { message: 'Database connection successful' };
    } else {
      throw new Error('Unexpected response from database');
    }
  } catch (error) {
    if (client && client.end) {
      await client.end().catch(() => {});
    }
    throw error;
  }
}

// Test AWS credentials (simple auth call)
async function testAWS() {
  if (!process.env.AWS_ACCESS_KEY_ID || !process.env.AWS_SECRET_ACCESS_KEY) {
    throw new Error('AWS credentials are not set');
  }

  AWS.config.update({
    accessKeyId: process.env.AWS_ACCESS_KEY_ID,
    secretAccessKey: process.env.AWS_SECRET_ACCESS_KEY,
    region: 'us-east-1'
  });

  const sts = new AWS.STS();

  try {
    await sts.getCallerIdentity().promise();
    return { message: 'AWS credentials are valid' };
  } catch (error) {
    // Check for specific "canary" indicators
    if (error.message.includes('CANARY') || 
        error.code === 'InvalidAccessKeyId' || 
        error.code === 'SignatureDoesNotMatch') {
      return { 
        success: false,
        error: error.message.includes('CANARY') 
          ? 'These appear to be test/canary credentials (expected behavior)'
          : `AWS credentials are invalid: ${error.message}`
      };
    }
    throw error;
  }
}

// Test Anthropic API key
async function testAnthropic() {
  if (!process.env.ANTHROPIC_API_KEY) {
    throw new Error('ANTHROPIC_API_KEY is not set');
  }

  return new Promise((resolve, reject) => {
