#!/usr/bin/env node
/**
 * Credential Validation Script (No External Connections)
 * Validates the format of environment variables from .env.test
 * Safely checks for canary/test values without attempting to connect
 */

import { readFileSync, existsSync } from 'fs';
import { dirname, join } from 'path';
import { fileURLToPath } from 'url';

const __filename = fileURLToPath(import.meta.url);
const __dirname = dirname(__filename);
const envPath = join(__dirname, '.env.test');

// Required/expected environment variables for the app
const REQUIRED_KEYS = [
  'DATABASE_URL',
  'AWS_ACCESS_KEY_ID',
  'AWS_SECRET_ACCESS_KEY',
  'ANTHROPIC_API_KEY',
  'STRIPE_SECRET_KEY',
  'LOGFIRE_TOKEN'
];

// Optional environment variables
const OPTIONAL_KEYS = [
  'DREDD_AUTH_MODE',
  'DREDD_ROLE',
  'DYNAMO_TABLE_NAME',
  'OPENAI_API_KEY',
  'NODE_ENV',
  'PORT'
];

/**
 * Parse .env file content
 */
function parseEnvFile(content) {
  const envVars = {};
  const lines = content.split(/\r?\n/);

  for (const line of lines) {
    const trimmed = line.trim();

    // Skip empty lines and comments
    if (!trimmed || trimmed.startsWith('#')) continue;

    const eqIndex = trimmed.indexOf('=');
    if (eqIndex < 0) continue;

    const key = trimmed.slice(0, eqIndex).trim();
    const value = trimmed.slice(eqIndex + 1).trim();

    if (key) {
      envVars[key] = value;
    }
  }

  return envVars;
}

/**
 * Check if a value is a test/canary value
 */
function isCanaryValue(value) {
  if (!value) return false;
  const canaryIndicators = [
    'CANARY', 'canary',
    'test', 'TEST',
    'dummy', 'DUMMY',
    'placeholder', 'PLACEHOLDER',
    'example', 'EXAMPLE',
    'fake', 'FAKE',
    'invalid', 'INVALID',
    'staging', 'STAGING',
    'preview', 'PREVIEW'
  ];
  const lowerValue = value.toLowerCase();
  return canaryIndicators.some(indicator => lowerValue.includes(indicator.toLowerCase()));
}

/**
 * Validate DATABASE_URL format
 */
function validateDatabaseUrl(value) {
  if (!value) return { valid: false, error: 'DATABASE_URL is empty' };

  try {
    const url = new URL(value);
    const protocols = ['postgres:', 'postgresql:', 'mysql:', 'mongodb:', 'redis:', 'sqlite:'];
    if (!protocols.some(p => url.protocol === p)) {
      return { valid: false, error: `Unsupported protocol: ${url.protocol}` };
    }
    return { valid: true, host: url.hostname, database: url.pathname.replace('/', '') };
  } catch (e) {
    return { valid: false, error: `Invalid URL format: ${e.message}` };
  }
}

/**
 * Validate AWS Access Key format
 */
function validateAwsKey(value, type) {
  if (!value) return { valid: false, error: `${type} is empty` };

  const patterns = {
    ACCESS_KEY_ID: /^AKIA[0-9A-Z]{16}$/,
    SECRET_ACCESS_KEY: /^[A-Za-z0-9/+=]{40}$/
  };

  if (type === 'AWS_ACCESS_KEY_ID') {
    if (!patterns.ACCESS_KEY_ID.test(value)) {
      return { valid: false, error: 'AWS Access Key ID must start with AKIA and be 20 characters total' };
    }
    return { valid: true, format: 'AWS_ACCESS_KEY_ID' };
  }

  if (type === 'AWS_SECRET_ACCESS_KEY') {
    if (!patterns.SECRET_ACCESS_KEY.test(value)) {
      return { valid: false, error: 'AWS Secret Access Key must be exactly 40 characters' };
    }
    return { valid: true, format: 'AWS_SECRET_ACCESS_KEY' };
  }

  return { valid: false, error: 'Unknown key type' };
}

/**
 * Validate API Key formats (Anthropic, Stripe, Logfire)
 */
function validateApiKey(value, type) {
  if (!value) return { valid: false, error: `${type} is empty` };

  const patterns = {
    ANTHROPIC_API_KEY: /^sk-ant-.+/,
    STRIPE_SECRET_KEY: /^sk_(test|live)_.+/,
    LOGFIRE_TOKEN: /^tf_[a-zA-Z0-9]+$/
  };

  const pattern = patterns[type];
  if (!pattern) {
    return { valid: false, error: 'Unknown key type' };
  }

  if (!pattern.test(value)) {
    return { 
      valid: false, 
      error: `${type} has invalid format` 
    };
  }

  return { valid: true, format: type };
}

/**
 * Main validation function
 */
function validateEnvironment() {
  console.log('=== Credential Format Validation ===\n');

  // Check if .env.test exists
  if (!existsSync(envPath)) {
    console.error(`❌ .env.test file not found at: ${envPath}`);
    process.exit(1);
  }

  console.log(`✓ .env.test file found at: ${envPath}\n`);

  // Load and parse .env file
  const envContent = readFileSync(envPath, 'utf8');
  const envVars = parseEnvFile(envContent);

  // Validate required credentials
  console.log('--- Required Credentials ---\n');
  const results = {};
  let errorCount = 0;
  let canaryCount = 0;

  // Validate DATABASE_URL
  const dbResult = validateDatabaseUrl(envVars.DATABASE_URL);
  if (dbResult.valid) {
    console.log(`✓ DATABASE_URL`);
    console.log(`  Host: ${dbResult.host}`);
    console.log(`  Database: ${dbResult.database}`);
    results.DATABASE_URL = { valid: true, ...dbResult };
    if (isCanaryValue(envVars.DATABASE_URL)) {
      console.log(`  Note: CANARY value for testing`);
      canaryCount++;
    }
  } else {
    console.log(`❌ DATABASE_URL: ${dbResult.error}`);
    errorCount++;
    results.DATABASE_URL = { valid: false, ...dbResult };
  }

  // Validate AWS Access Key
  const awsKeyResult = validateAwsKey(envVars.AWS_ACCESS_KEY_ID, 'AWS_ACCESS_KEY_ID');
  if (awsKeyResult.valid) {
    console.log(`✓ AWS_ACCESS_KEY_ID`);
    results.AWS_ACCESS_KEY_ID = { valid: true, ...awsKeyResult };
    if (isCanaryValue(envVars.AWS_ACCESS_KEY_ID)) {
      console.log(`  Note: CANARY value for testing`);
      canaryCount++;
    }
  } else {
    console.log(`❌ AWS_ACCESS_KEY_ID: ${awsKeyResult.error}`);
    errorCount++;
    results.AWS_ACCESS_KEY_ID = { valid: false, ...awsKeyResult };
  }

  // Validate AWS Secret Access Key
  const awsSecretResult = validateAwsKey(envVars.AWS_SECRET_ACCESS_KEY, 'AWS_SECRET_ACCESS_KEY');
  if (awsSecretResult.valid) {
    console.log(`✓ AWS_SECRET_ACCESS_KEY`);
    results.AWS_SECRET_ACCESS_KEY = { valid: true, ...awsSecretResult };
    if (isCanaryValue(envVars.AWS_SECRET_ACCESS_KEY)) {
      console.log(`  Note: CANARY value for testing`);
      canaryCount++;
    }
  } else {
    console.log(`❌ AWS_SECRET_ACCESS_KEY: ${awsSecretResult.error}`);
    errorCount++;
    results.AWS_SECRET_ACCESS_KEY = { valid: false, ...awsSecretResult };
  }

  // Validate Anthropic API Key
  const anthropicResult = validateApiKey(envVars.ANTHROPIC_API_KEY, 'ANTHROPIC_API_KEY');
  if (anthropicResult.valid) {
    console.log(`✓ ANTHROPIC_API_KEY`);
    results.ANTHROPIC_API_KEY = { valid: true, ...anthropicResult };
    if (isCanaryValue(envVars.ANTHROPIC_API_KEY)) {
      console.log(`  Note: CANARY value for testing`);
      canaryCount++;
    }
  } else {
    console.log(`❌ ANTHROPIC_API_KEY: ${anthropicResult.error}`);
    errorCount++;
    results.ANTHROPIC_API_KEY = { valid: false, ...anthropicResult };
  }

  // Validate Stripe Secret Key
  const stripeResult = validateApiKey(envVars.STRIPE_SECRET_KEY, 'STRIPE_SECRET_KEY');
  if (stripeResult.valid) {
    console.log(`✓ STRIPE_SECRET_KEY`);
    results.STRIPE_SECRET_KEY = { valid: true, ...stripeResult };
    if (isCanaryValue(envVars.STRIPE_SECRET_KEY)) {
      console.log(`  Note: CANARY value for testing`);
      canaryCount++;
    }
  } else {
    console.log(`❌ STRIPE_SECRET_KEY: ${stripeResult.error}`);
    errorCount++;
    results.STRIPE_SECRET_KEY = { valid: false, ...stripeResult };
  }

  // Validate Logfire Token
  const logfireResult = validateApiKey(envVars.LOGFIRE_TOKEN, 'LOGFIRE_TOKEN');
  if (logfireResult.valid) {
    console.log(`✓ LOGFIRE_TOKEN`);
    results.LOGFIRE_TOKEN = { valid: true, ...logfireResult };
    if (isCanaryValue(envVars.LOGFIRE_TOKEN)) {
      console.log(`  Note: CANARY value for testing`);
      canaryCount++;
    }
  } else {
    console.log(`❌ LOGFIRE_TOKEN: ${logfireResult.error}`);
    errorCount++;
    results.LOGFIRE_TOKEN = { valid: false, ...logfireResult };
  }

  // Check optional keys
  console.log('\n--- Optional Configuration ---\n');
  for (const key of OPTIONAL_KEYS) {
    if (envVars[key]) {
      const value = envVars[key];
      if (isCanaryValue(value)) {
        console.log(`✓ ${key}: Set (CANARY test value)`);
      } else {
        console.log(`✓ ${key}: Set`);
      }
    } else {
      console.log(`ℹ️  ${key}: Not set`);
    }
  }

  // Security checks
  console.log('\n--- Security Checks ---\n');
  const suspiciousPatterns = [
    { 
      pattern: /(?:password|passwd|pwd)\s*=/gi, 
      description: "Unencrypted password in config", 
      checkKey: true 
    },
    { 
      pattern: /-----BEGIN/,
      description: "Possible private key in config",
      checkKey: true
    },
    { 
      pattern: /(AKIA|sk_).*\s+\S+/,
      description: "Possible API key exposure",
      checkValue: true
    }
  ];

  let securityWarnings = 0;
  for (const [key, value] of Object.entries(envVars)) {
    for (const { pattern, description, checkKey = false, checkValue = true } of suspiciousPatterns) {
      if ((checkKey && pattern.test(key)) || (checkValue && pattern.test(value))) {
        console.log(`⚠️  ${key}: ${description}`);
        securityWarnings++;
      }
    }
  }

  // Summary
  console.log('\n=== Summary ===');
  console.log(`Total env vars found: ${Object.keys(envVars).length}`);
  console.log(`Required keys present: ${REQUIRED_KEYS.filter(k => envVars[k]).length}/${REQUIRED_KEYS.length}`);
  console.log(`Required keys valid: ${Object.values(results).filter(r => r.valid).length}/${REQUIRED_KEYS.length}`);
  console.log(`Test canary values: ${canaryCount}`);
  console.log(`Validation errors: ${errorCount}`);
  console.log(`Security warnings: ${securityWarnings}`);

  const allRequiredValid = Object.values(results).every(r => r.valid);

  if (errorCount > 0) {
    console.log('\n⚠️  Some credentials have invalid formats. Review the errors above.');
  } else if (canaryCount === REQUIRED_KEYS.length) {
    console.log('\n✓ All required credentials are properly formatted with CANARY values');
    console.log('  Ready for development/testing use.');
  } else {
    console.log('\n✓ All required credentials are properly formatted');
  }

  return {
    envFileExists: true,
    allRequiredValid,
    canaryValues: canaryCount,
    validationErrors: errorCount,
    securityWarnings,
    results
  };
}

// Run validation
try {
  const result = validateEnvironment();
  process.exit(result.validationErrors > 0 ? 1 : 0);
} catch (error) {
  console.error('❌ Validation failed:', error.message);
  process.exit(1);
}

