      status: 'canary', 
      note: 'Value is a test/canary value - actual connection not attempted' 
    };
  }

  // Try PostgreSQL connection using psql CLI
  try {
    const { spawn } = await import('child_process');
    const psql = spawn('psql', [url, '-c', 'SELECT 1']);

    let stdout = '';
    let stderr = '';

    psql.stdout.on('data', data => stdout += data.toString());
    psql.stderr.on('data', data => stderr += data.toString());

    await new Promise((resolve, reject) => {
      psql.on('close', code => {
        if (code === 0 && stdout.includes('1')) {
          resolve({ success: true });
        } else {
          reject(new Error(`psql exited with code ${code}`));
        }
      });
      psql.on('error', reject);
    });

    console.log('✓ Database connection successful');
    return { status: 'valid' };
  } catch (error) {
    console.log('❌ Database connection failed');
    console.log(`   Error: ${error.message}`);
    return { status: 'error', error: error.message };
  }
}

