  console.log('⚠️  Will test with AWS SDK if available');

  try {
    const { STSClient, GetCallerIdentityCommand } = await import('@aws-sdk/client-sts');
    const sts = new STSClient({
      region: 'us-east-1',
      credentials: {
        accessKeyId: keyId,
        secretAccessKey: secret
      }
    });

    const command = new GetCallerIdentityCommand({});
    await sts.send(command);

    console.log('✓ AWS credentials are valid');
    return { status: 'valid' };
  } catch (error) {
    console.log('❌ AWS credentials check failed:', error.message);
    console.log('   (AWS SDK might not be installed)');
    return { status: 'error', error: error.message };
  }
}

// Main function
async function main() {
  console.log('=== Connectivity Verification ===');
  console.log(`Timestamp: ${new Date().toISOString()}\n`);

  const results = {
    database: await testDatabase(),
    aws: await testAWS(),
    anthropic: await testAnthropic(),
    stripe: await testStripe(),
    logfire: await testLogfire(),
  };

  // Summary
  console.log('\n=== Summary ===');

  let validCount = 0;
  let canaryCount = 0;
  let errorCount = 0;
  let missingCount = 0;

  for (const [service, result] of Object.entries(results)) {
    switch (result.status) {
      case 'valid':
        console.log(`✓ ${service.toUpperCase()}: Valid`);
        validCount++;
        break;
      case 'canary':
        console.log(`⚠️  ${service.toUpperCase()}: Canary/Test value (skipped)`);
        if (result.note) console.log(`   ${result.note}`);
        canaryCount++;
        break;
      case 'error':
        console.log(`❌ ${service.toUpperCase()}: Error`);
        if (result.error) console.log(`   ${result.error}`);
        errorCount++;
        break;
      case 'missing':
        console.log(`❌ ${service.toUpperCase()}: Missing`);
        missingCount++;
        break;
      default:
        console.log(`ℹ️  ${service.toUpperCase()}: ${result.status || 'uncertain'}`);
        if (result.response) console.log(`   Response: ${result.response}`);
    }
  }

  console.log(`\nResults: ${validCount} valid, ${canaryCount} canary, ${errorCount} errors, ${missingCount} missing`);

  if (canaryCount === Object.keys(results).length) {
    console.log('\n⚠️  All credentials are CANARY values. Edit .env.test with real values to test connectivity.');
    console.log('   This verification script will skip API calls to prevent false positives.');
  } else if (validCount > 0) {
    console.log('\n✓ Some credentials are valid and can connect to services');
  }
}

main().catch(console.error);
